// The structured data a procedure page carries, from its D1 record: Bioschemas LabProtocol for a protocol
// (https://bioschemas.org/profiles/LabProtocol/0.9-DRAFT; every LabProtocol version is a draft), schema.org Recipe for a
// recipe, following Google's recipe structured-data guidance, and schema.org HowTo for a computational procedure, the closest type
// for a sequence of commands with tools and supplies. Only facts the record states: a gap stays out.

import { thing } from "@drdustinedwards/site-helpers/schema";
import { htmlToText, isoDuration } from "@drdustinedwards/site-helpers/text";

import { citeFacts } from "./cite.mjs";
import { readConditions } from "./marks.mjs";

const LAB_PROTOCOL_PROFILE = "https://bioschemas.org/profiles/LabProtocol/0.9-DRAFT";

/** A number as a step writes it: "13,000" is 13000. @param {string} n */
const numeral = (n) => Number(n.replaceAll(",", ""));

/**
 * The protocol's conditions as 0.9-DRAFT's `parameter` (docs/KNOWLEDGE-BASE.md, P4): every temperature and spin its steps
 * state, once each, in the order first stated. The profile puts them on the protocol as a whole, not on a step, and these
 * are the conditions the compile already reads (marks.mjs readConditions): from a step's words, and the g-force its
 * SPIN flag states. Nothing is typed twice.
 *
 * @param {import("./render.mjs").ProcedureRecord} record
 */
export function protocolParameters(record) {
  // Keyed by the condition, so one stated in several steps is one parameter, at the place it was first stated.
  /** @type {Map<string, Record<string, unknown>>} */
  const seen = new Map();
  for (const section of record.sections) {
    for (const block of section.blocks) {
      if (block.type !== "steps") continue;
      for (const step of block.steps) {
        // A row compiled before the conditions were stored has none until the next sync rewrites it.
        for (const t of step.temperatures ?? []) {
          seen.set(`t:${t.min}:${t.max}`, {
            "@type": "PropertyValue",
            name: "Temperature",
            ...(t.min === t.max ? { value: t.min } : { minValue: t.min, maxValue: t.max }),
            unitCode: "CEL",
            unitText: "°C",
          });
        }
        const flagged = (step.spin ?? []).flatMap((s) => readConditions(s).spins);
        for (const spin of [...(step.spins ?? []), ...flagged]) {
          const [low = "", high] = spin.speed.split(/\s*to\s*/);
          const range =
            high === undefined
              ? { value: numeral(low) }
              : { minValue: numeral(low), maxValue: numeral(high) };
          seen.set(`s:${spin.speed}:${spin.unit}`, {
            "@type": "PropertyValue",
            name: spin.unit === "rpm" ? "Rotor speed" : "Relative centrifugal force",
            ...range,
            unitText: spin.unit === "rpm" ? "rpm" : "x g",
          });
        }
      }
    }
  }
  return [...seen.values()];
}

/**
 * The procedure a variant was copied from, as `isBasedOn` names it (P3): its address, at the version copied when there is
 * a frozen copy of it, and its title. Resolved at request time from the parent's row (lineage.server.ts).
 *
 * @param {import("./lineage.mjs").Lineage | null} lineage
 * @param {string} origin
 */
function lineageWork(lineage, origin) {
  if (!lineage?.href) return [];
  return [
    {
      "@type": "CreativeWork",
      name: lineage.title,
      url: `${origin}${lineage.href}`,
      ...(lineage.version ? { version: lineage.version } : {}),
    },
  ];
}

/**
 * "20 minutes", "1.5 hours" as ISO 8601; null for anything else.
 *
 * @param {string | null} value
 */
function minutesToIso(value) {
  const m = /^(\d+(?:\.\d+)?) (minutes?|hours?)$/.exec(String(value ?? ""));
  if (!m) return null;
  const minutes = Math.round(Number(m[1]) * (m[2]?.startsWith("hour") ? 60 : 1));
  return isoDuration(minutes * 60) ?? "PT0M";
}

/**
 * @param {import("./render.mjs").ProcedureRecord} record
 * @param {string} origin
 * @param {{ "@type": string, "@id": string, name: string, url: string }} person
 * @param {import("./lineage.mjs").Lineage | null} [lineage] the procedure this one is a variant of
 */
export function procedureJsonLd(record, origin, person, lineage = null) {
  const url = `${origin}${record.path}`;
  const steps = record.sections.flatMap((section) => {
    const items = section.blocks.flatMap((b) => (b.type === "steps" ? b.steps : []));
    if (items.length === 0) return [];
    return [
      {
        "@type": "HowToSection",
        name: section.title,
        itemListElement: items.map((step) => ({
          "@type": "HowToStep",
          position: step.number,
          text: step.text,
          url: `${url}#${section.id}`,
          ...(step.photos[0] ? { image: `${origin}${step.photos[0].src}` } : {}),
        })),
      },
    ];
  });
  const basedOn = [
    ...lineageWork(lineage, origin),
    ...record.basedOn.map((s) => ({
      "@type": "CreativeWork",
      name: s.citation,
      ...(s.doi
        ? { identifier: `https://doi.org/${s.doi}`, url: `https://doi.org/${s.doi}` }
        : s.url
          ? { url: s.url }
          : {}),
    })),
  ];
  const cite = citeFacts(record);
  // Prelum's `thing` writes the context and the type, then these, and drops an empty field.
  const common = {
    "@id": `${url}#procedure`,
    name: record.title,
    description: record.description,
    url,
    author: person,
    ...(record.updated ? { dateModified: record.updated } : {}),
    ...(record.version ? { version: record.version } : {}),
    ...(cite?.doi ? { identifier: `https://doi.org/${cite.doi}` } : {}),
    ...(basedOn.length ? { isBasedOn: basedOn } : {}),
    ...(record.references.length
      ? { citation: record.references.map((html) => htmlToText(html)) }
      : {}),
  };

  if (record.profile === "protocol") {
    const totalTime = minutesToIso(record.time.total);
    const parameters = protocolParameters(record);
    return thing("LabProtocol", {
      ...common,
      "http://purl.org/dc/terms/conformsTo": { "@id": LAB_PROTOCOL_PROFILE },
      reagent: record.materials.map((m) => m.display),
      labEquipment: record.equipment.map((e) => e.name),
      ...(record.biosafetyLevel
        ? {
            additionalProperty: {
              "@type": "PropertyValue",
              name: "Biosafety level",
              value: record.biosafetyLevel,
            },
          }
        : {}),
      ...(record.biosafety
        ? {
            bioSample: [record.biosafety.organism, record.biosafety.strain]
              .filter(Boolean)
              .join(" "),
          }
        : {}),
      ...(record.expectedResultsHtml
        ? { protocolOutcome: htmlToText(record.expectedResultsHtml) }
        : {}),
      ...(record.limitationsHtml ? { protocolLimitation: htmlToText(record.limitationsHtml) } : {}),
      ...(totalTime ? { totalTime } : {}),
      ...(parameters.length ? { parameter: parameters } : {}),
      step: steps,
    });
  }

  if (record.profile === "recipe") {
    const prep = minutesToIso(record.prepTime);
    const cook = minutesToIso(record.cookTime);
    const minutes = (/** @type {string | null} */ d) => {
      const m = /^PT(?:(\d+)H)?(?:(\d+)M)?$/.exec(d ?? "");
      return m ? Number(m[1] ?? 0) * 60 + Number(m[2] ?? 0) : null;
    };
    const total =
      prep && cook ? minutesToIso(`${(minutes(prep) ?? 0) + (minutes(cook) ?? 0)} minutes`) : null;
    return thing("Recipe", {
      ...common,
      ...(record.image ? { image: [`${origin}${record.image.src}`] } : {}),
      ...(record.servings ? { recipeYield: String(record.servings) } : {}),
      ...(record.cuisine ? { recipeCuisine: record.cuisine } : {}),
      ...(record.category ? { recipeCategory: record.category } : {}),
      ...(prep ? { prepTime: prep } : {}),
      ...(cook ? { cookTime: cook } : {}),
      ...(total ? { totalTime: total } : {}),
      recipeIngredient: record.materials.map((m) =>
        m.amount ? `${m.amount} ${m.display}` : m.display,
      ),
      recipeInstructions: steps,
    });
  }

  return thing("HowTo", {
    ...common,
    tool: record.materials
      .filter((m) => m.kind === "software")
      .map((m) => ({
        "@type": "HowToTool",
        name: m.version ? `${m.display} ${m.version}` : m.display,
      })),
    supply: record.materials
      .filter((m) => m.kind !== "software")
      .map((m) => ({ "@type": "HowToSupply", name: m.display })),
    step: steps,
  });
}

app/kb/procedures/lineage.mjs.source:
// A variant's lineage (docs/KNOWLEDGE-BASE.md, P3): the procedure it was copied from with the editor's Duplicate, as the
// page, the twin and the JSON-LD name it. The file holds only `forked_from: { slug, version }`; the parent's title and
// address are its own facts, read from its row when the page is served, so a renamed parent reads right everywhere.

import { BASES } from "../bases.mjs";
import { versionPath } from "./cite.mjs";

/** A record's page: its profile's entry root and its slug. @param {string} profile @param {string} slug */
export function entryPathFor(profile, slug) {
  return `${BASES.find((b) => b.profile === profile)?.entryRoot ?? "/research/protocols/"}${slug}`;
}

/**
 * @typedef {{ title: string, href: string | null, version: string | null }} Lineage
 */

/**
 * Where a variant points: the frozen copy of the version it was copied at when there is one, else the parent's live page,
 * else (a parent not published) its name with no link.
 *
 * @param {{ slug: string, version: string | null } | null} forkedFrom
 * @param {string} profile
 * @param {{ live: { title: string, path: string } | null, frozen: { title: string } | null }} parent
 * @returns {Lineage | null}
 */
export function resolveLineage(forkedFrom, profile, parent) {
  if (!forkedFrom) return null;
  const path = entryPathFor(profile, forkedFrom.slug);
  if (forkedFrom.version && parent.frozen)
    return {
      title: parent.frozen.title,
      href: versionPath(path, forkedFrom.version),
      version: forkedFrom.version,
    };
  if (parent.live)
    return { title: parent.live.title, href: parent.live.path, version: forkedFrom.version };
  return { title: forkedFrom.slug, href: null, version: forkedFrom.version };
}

/** "Phage DNA extraction, version 2": the words the lineage is shown in. @param {Lineage} lineage */
export const lineageText = (lineage) =>
  `${lineage.title}${lineage.version ? `, version ${lineage.version}` : ""}`;

/** The twin's fact line for a lineage, as the page's fact reads. @param {Lineage} lineage @param {string} origin */
const lineageMarkdown = (lineage, origin) =>
  `- Based on: ${lineage.href ? `[${lineageText(lineage)}](${origin}${lineage.href})` : lineageText(lineage)}`;

/**
 * The fact the stored twin carries for a variant: the parent's file name and version, all the compile knows. The twin's
 * routes swap it for the parent's title and address when they serve it (`withLineage`).
 *
 * @param {{ slug: string, version: string | null }} forkedFrom
 */
export const storedLineage = (forkedFrom) =>
  `${forkedFrom.slug}${forkedFrom.version ? `, version ${forkedFrom.version}` : ""}`;

/**
 * A twin with its stored lineage fact read out in full: the parent's title, linked to the copy it was taken from.
 *
 * @param {string} markdown
 * @param {{ forkedFrom: { slug: string, version: string | null } | null }} record
 * @param {Lineage | null} lineage
 * @param {string} origin
 */
export function withLineage(markdown, record, lineage, origin) {
  if (!record.forkedFrom || !lineage) return markdown;
  return markdown.replace(
    `- Based on: ${storedLineage(record.forkedFrom)}\n`,
    `${lineageMarkdown(lineage, origin)}\n`,
  );
}

/**
 * What is wrong with a variant's `forked_from` against the procedures in the repository (P3): the parent is a file
 * here, of the same profile, and the version named is one the parent states (its current version or one in its history),
 * which is a version that is or will be frozen. The shape is validate.mjs's; this is the corpus check:content runs.
 *
 * @param {{ forkedFrom: { slug: string, version: string | null } | null, profile: string }} record
 * @param {Map<string, { profile: string, version: string | null, history: Array<{ version: string }> }>} procedures by slug
 * @returns {string[]}
 */
export function lineageErrors(record, procedures) {
  const from = record.forkedFrom;
  if (!from) return [];
  const parent = procedures.get(from.slug);
  if (!parent) return [`forked_from names ${from.slug}, which is not a procedure here`];
  if (parent.profile !== record.profile)
    return [
      `forked_from names ${from.slug}, a ${parent.profile}; a variant keeps its parent's profile (${record.profile})`,
    ];
  if (!from.version) return [];
  const stated = new Set([parent.version, ...parent.history.map((h) => h.version)].filter(Boolean));
  return stated.has(from.version)
    ? []
    : [
        `forked_from names version ${from.version} of ${from.slug}, which states ${[...stated].join(", ") || "no version"}`,
      ];
}

app/kb/procedures/marks.mjs.source:
// The inline marks a procedure step carries, in Cooklang's syntax (https://cooklang.org/docs/spec/):
// `@material{20%µl}`, `#equipment{}`, `~{10%minutes}`, plus the cooklang-rs alias form
// `@material|shown words{20%µl}` and its fixed-amount form `{=20%µl}`. The official parser
// (@cooklang/cooklang) is a pre-1.0 WASM build whose model is recipes only, so the site reads the marks
// itself and keeps Cooklang's spelling, so a file stays readable by Cooklang tools.
//
// Temperatures and spin speeds are read from the words, not marked, so a step stays the sentence a
// person wrote: "Incubate at 55 to 60 °C" is both.

/** A mark starts at the start of the text or after whitespace, so `(#refs)` and `a@b.c` are text. */
const MARK_START = /[@#~]/g;

/** A multi-word name runs to its `{`; it cannot cross another mark, a brace or a line. */
const BRACED = /^([@#])([^@#~{}\n]{1,160}?)\{([^{}\n]*)\}/u;
const SINGLE = /^([@#])([\p{L}\p{N}_-]+)/u;
const TIMER = /^~([^@#~{}\n]{0,60}?)\{([^{}\n]*)\}/u;

/**
 * Stretches of the text where a mark is never read: inline code, a link's target, an autolink.
 *
 * @param {string} text
 * @returns {Array<[number, number]>}
 */
function protectedRanges(text) {
  /** @type {Array<[number, number]>} */
  const ranges = [];
  for (const pattern of [/`[^`\n]*`/g, /\]\([^)\n]*\)/g, /<[a-z]+:[^>\n]*>/gi]) {
    for (const match of text.matchAll(pattern))
      ranges.push([match.index, match.index + match[0].length]);
  }
  return ranges;
}

/**
 * A number as written: "20", "1.25", "10,000", "1/2", "1 1/2".
 *
 * @param {string} raw
 * @returns {number | null}
 */
export function parseNumber(raw) {
  const s = raw.trim().replaceAll(",", "");
  let m = /^(\d+) (\d+)\/(\d+)$/.exec(s);
  if (m) return Number(m[1]) + Number(m[2]) / Number(m[3]);
  m = /^(\d+)\/(\d+)$/.exec(s);
  if (m) return Number(m[1]) / Number(m[2]);
  return /^-?\d+(?:\.\d+)?$/.test(s) ? Number(s) : null;
}

/**
 * The inside of a mark's braces: `20%µl`, `=20%µl`, `1.25 to 5%µl`, `2`, or empty.
 *
 * @param {string} inner
 * @returns {{ raw: string, amount: string, unit: string, fixed: boolean, min: number | null, max: number | null } | null}
 */
export function parseQuantity(inner) {
  let body = inner.trim();
  if (!body) return null;
  const fixed = body.startsWith("=");
  if (fixed) body = body.slice(1).trim();
  const at = body.indexOf("%");
  const amount = (at < 0 ? body : body.slice(0, at)).trim();
  const unit = at < 0 ? "" : body.slice(at + 1).trim();
  const range = /^(.+?)\s*(?:-|to)\s*(.+)$/.exec(amount);
  const min = parseNumber(range ? (range[1] ?? "") : amount);
  const max = range ? parseNumber(range[2] ?? "") : min;
  return { raw: inner, amount, unit, fixed, min, max: min === null ? null : max };
}

/**
 * @typedef {{ type: "text", value: string }} TextSegment
 * @typedef {ReturnType<typeof parseQuantity>} Quantity
 * @typedef {{ type: "material", name: string, display: string, quantity: Quantity }} MaterialSegment
 * @typedef {{ type: "equipment", name: string, display: string }} EquipmentSegment
 * @typedef {{ type: "timer", label: string, quantity: Quantity }} TimerSegment
 * @typedef {TextSegment | MaterialSegment | EquipmentSegment | TimerSegment} Segment
 */

/**
 * Where each mark sits in the text, with the parts it was written with: the one reading of the marks, which tokenize turns
 * into words and the admin editor turns into chips (app/kb/step-marks.mjs), so the two can never split a step differently.
 *
 * @param {string} text
 * @returns {Array<{ start: number, end: number, sign: "@" | "#" | "~", name: string, shown: string, braces: string | null }>}
 */
export function markSpans(text) {
  const ranges = protectedRanges(text);
  const inRange = (/** @type {number} */ i) => ranges.some(([a, b]) => i >= a && i < b);
  /** @type {Array<{ start: number, end: number, sign: "@" | "#" | "~", name: string, shown: string, braces: string | null }>} */
  const out = [];
  let last = 0;
  for (const hit of text.matchAll(MARK_START)) {
    const i = hit.index;
    if (i < last || inRange(i)) continue;
    const before = i === 0 ? "" : (text[i - 1] ?? "");
    if (before && !/\s/.test(before)) continue;
    const rest = text.slice(i);
    if (rest[0] === "~") {
      const m = TIMER.exec(rest);
      if (!m) continue;
      out.push({
        start: i,
        end: i + m[0].length,
        sign: "~",
        name: (m[1] ?? "").trim(),
        shown: "",
        braces: m[2] ?? "",
      });
      last = i + m[0].length;
      continue;
    }
    const m = BRACED.exec(rest) ?? SINGLE.exec(rest);
    if (!m) continue;
    const [name, shown] = (m[2] ?? "").split("|").map((part) => part.trim());
    out.push({
      start: i,
      end: i + m[0].length,
      sign: /** @type {"@" | "#"} */ (m[1]),
      name: name ?? "",
      shown: shown ?? "",
      braces: m[3] === undefined ? null : m[3],
    });
    last = i + m[0].length;
  }
  return out;
}

/**
 * The text split into words and marks.
 *
 * @param {string} text
 * @returns {Segment[]}
 */
export function tokenize(text) {
  /** @type {Segment[]} */
  const out = [];
  let last = 0;
  for (const span of markSpans(text)) {
    if (span.start > last) out.push({ type: "text", value: text.slice(last, span.start) });
    if (span.sign === "~")
      out.push({ type: "timer", label: span.name, quantity: parseQuantity(span.braces ?? "") });
    else if (span.sign === "@") {
      out.push({
        type: "material",
        name: span.name,
        display: span.shown || span.name,
        quantity: span.braces === null ? null : parseQuantity(span.braces),
      });
    } else out.push({ type: "equipment", name: span.name, display: span.shown || span.name });
    last = span.end;
  }
  if (text.length > last) out.push({ type: "text", value: text.slice(last) });
  return out;
}

/**
 * A number printed the way the file would write it: no trailing zeros, thousands with commas.
 *
 * @param {number} n
 */
export function formatNumber(n) {
  const rounded = Math.round(n * 1000) / 1000;
  return rounded.toLocaleString("en-US", { maximumFractionDigits: 3 });
}

/**
 * A quantity as words, scaled by `factor` unless it is fixed or not a number.
 *
 * @param {NonNullable<Quantity>} q
 * @param {number} [factor]
 */
export function formatQuantity(q, factor = 1) {
  let amount = q.amount;
  if (factor !== 1 && !q.fixed && q.min !== null) {
    amount =
      q.max !== null && q.max !== q.min
        ? `${formatNumber(q.min * factor)} to ${formatNumber(q.max * factor)}`
        : formatNumber(q.min * factor);
  }
  return q.unit ? `${amount} ${q.unit}` : amount;
}

/**
 * The words a segment stands for on the page.
 *
 * @param {Segment} segment
 * @param {number} [factor]
 */
export function segmentText(segment, factor = 1) {
  switch (segment.type) {
    case "text":
      return segment.value;
    case "material":
      return segment.quantity
        ? `${formatQuantity(segment.quantity, factor)} of ${segment.display}`
        : segment.display;
    case "equipment":
      return segment.display;
    case "timer":
      return segment.quantity ? formatQuantity(segment.quantity) : segment.label;
  }
}

/** "37 °C", "55 to 60 °C", "-80 °C", "55-60 °C". Exported for the editor, which shows each as a chip. */
export const TEMPERATURE = /(-?\d+(?:\.\d+)?)(?:\s*(?:to|-)\s*(-?\d+(?:\.\d+)?))?\s*°C/g;
/** "10,000 rpm", "12,000 x g", "10,000 to 15,000 x g". */
const SPIN = /(?<![\d.,])(\d[\d,]*(?:\s*to\s*\d[\d,]*)?)\s*(rpm|x g)\b/g;

/**
 * The temperatures and spins a step's words state.
 *
 * @param {string} text the step with its marks already turned into words
 */
export function readConditions(text) {
  const temperatures = [...text.matchAll(TEMPERATURE)].map((m) => ({
    min: Number(m[1]),
    max: m[2] === undefined ? Number(m[1]) : Number(m[2]),
    text: m[0],
  }));
  const spins = [...text.matchAll(SPIN)].map((m) => ({
    speed: (m[1] ?? "").trim(),
    unit: m[2] === "rpm" ? "rpm" : "x g",
    text: m[0],
  }));
  return { temperatures, spins };
}

app/kb/registry/catalog.mjs.source:
// How the registry reads on the site (docs/REGISTRY.md): its addresses, the master inventory over every kind and the
// phages, and each kind's own catalog, declared once for Capsomer's catalog so the page, its facets and counts, its
// sort menu and the markdown twin all read one declaration. Pure: the routes hand it the rows they read from D1.
// Nothing is typed again here. A primer's length, GC content, reverse complement and Tm come from its sequence, the
// protocols that use it are found by that sequence, and a phage in the inventory is read from the phages table, never
// copied into the registry.

import { mdLink } from "../md-link.mjs";
import { defineCatalog } from "capsomer/behavior/catalog";

import { HOSTS } from "../../lib/phages/compile.mjs";
import { reverseComplement } from "../../lib/primers.mjs";
import { KINDS } from "./kinds.mjs";
import { MAX_MISMATCHES, pairProducts, placePrimer } from "./align.mjs";
import { missingReason, primerFacts, stated } from "./primer.mjs";
import { designationOf } from "./strain.mjs";
import { NEB_TM_CALCULATOR, TM_CONDITIONS, annealingSentence, tmStatement } from "./tm.mjs";
import { mdCell, plural } from "@drdustinedwards/site-helpers/text";

/** The master inventory, and the root every kind's page sits under. */
export const LAB_PATH = "/research/lab";

/** The kind's page, from its plural: /research/lab/primers. @param {string} kind @param {Record<string, import("./kinds.mjs").KindSpec>} [kinds] */
export function kindPath(kind, kinds = KINDS) {
  return `${LAB_PATH}/${kinds[kind]?.plural ?? kind}`;
}

/** An item's page: /research/lab/primers/lco1490. @param {string} kind @param {string} id @param {Record<string, import("./kinds.mjs").KindSpec>} [kinds] */
export function itemPath(kind, id, kinds = KINDS) {
  return `${kindPath(kind, kinds)}/${id}`;
}

/**
 * The kind a URL segment names (its plural), or null.
 *
 * @param {string} segment
 * @param {Readonly<Record<string, import("./kinds.mjs").KindSpec>>} [kinds]
 */
export function kindFromSegment(segment, kinds = KINDS) {
  return Object.keys(kinds).find((kind) => kinds[kind]?.plural === segment) ?? null;
}

/**
 * The library's tabs for the registry: one for each kind that has a published item, linking to the kind's page, in the
 * order the kinds are defined. A kind with no item has no tab, so none points at an empty page.
 *
 * @param {import("./kinds.mjs").RegistryItem[]} items
 * @param {Readonly<Record<string, import("./kinds.mjs").KindSpec>>} [kinds]
 */
export function registryTabs(items, kinds = KINDS) {
  return Object.keys(kinds).flatMap((kind) => {
    const count = items.filter((item) => item.kind === kind).length;
    const plural = kinds[kind]?.plural ?? kind;
    return count === 0
      ? []
      : [
          {
            id: plural,
            label: plural.charAt(0).toUpperCase() + plural.slice(1),
            count,
            href: kindPath(kind, kinds),
          },
        ];
  });
}

/** An item's markdown twin: its name as the title over the lines, with runs of blank lines collapsed. @param {string} name @param {string[]} lines */
function itemTwin(name, lines) {
  return `# ${name}\n\n${lines
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim()}\n`;
}

/**
 * A primer as the pages read it: the record's own fields, the literature as read (and what could not be), and what is
 * computed: from its sequence, its length, GC content, Tm and reverse complement; from its reference, its placement; and by
 * comparison, whether its sequence matches the one the paper prints. Nothing computed is stored.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 */
export function primerRow(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  const sequence = stated(f.sequence);
  const reference = stated(f.reference);
  const facts = sequence ? primerFacts(sequence) : { length: null, gcPercent: null, tm: null };
  const printed = stated(f.published_sequence);
  return {
    id: item.id,
    path: itemPath("primer", item.id),
    name: item.name,
    sequence,
    reverseComplement: sequence && /^[ACGT]+$/.test(sequence) ? reverseComplement(sequence) : null,
    direction: stated(f.direction),
    target: stated(f.target),
    set: stated(f.set),
    reference,
    // Where it binds the reference, computed: null when it has no reference or binds nowhere within the mismatch limit.
    placement: sequence && reference ? placePrimer(sequence, reference) : null,
    // What the literature says, as read. Each `...Missing` is the reason it could not be found, shown so it is not hunted for.
    publishedIn: stated(f.published_in),
    publishedInMissing: missingReason(f.published_in),
    publishedDoi: stated(f.published_doi),
    publishedUrl: stated(f.published_url),
    publishedName: stated(f.published_name),
    publishedNameMissing: missingReason(f.published_name),
    publishedSequence: printed,
    publishedSequenceMissing: missingReason(f.published_sequence),
    publishedProduct: stated(f.published_product),
    publishedProductMissing: missingReason(f.published_product),
    // A comparison, never a field: null when the paper's sequence was not read, true when the stored one equals it.
    matchesPublished: printed && sequence ? printed === sequence : null,
    length: facts.length,
    gcPercent: facts.gcPercent,
    tm: facts.tm,
    draft: item.status === "draft",
  };
}

/** @typedef {ReturnType<typeof primerRow>} PrimerRow */

/**
 * The primers as rows with their pair's product computed, which a row alone cannot say: the product needs both primers of a
 * set, placed on their one reference.
 *
 * @param {import("./kinds.mjs").RegistryItem[]} items
 */
export function primerRows(items) {
  const rows = items.filter((item) => item.kind === "primer").map(primerRow);
  return rows.map((row) => ({ ...row, product: pairProduct(row, rows) }));
}

/** @typedef {ReturnType<typeof primerRows>[number]} PrimerListRow */

const DIRECTION_LABELS = /** @type {Record<string, string>} */ ({
  forward: "Forward",
  reverse: "Reverse",
  probe: "Probe",
});

/**
 * One line of a pair's product as the catalog and the twin show it: "281 bp", and "at 2 sites" when the pair binds twice (the
 * two LTRs of a provirus), or each size when the sites differ.
 *
 * @param {{ products: Array<{ length: number }> } | null} pair
 */
export function productText(pair) {
  if (!pair) return null;
  const sizes = [...new Set(pair.products.map((p) => p.length))];
  const text = sizes.map((s) => `${s} bp`).join(" or ");
  return pair.products.length > 1 && sizes.length === 1
    ? `${text} at ${pair.products.length} sites`
    : text;
}

