// The phage table's one declaration (docs/PHAGES.md): the fields a phage is searched, filtered, sorted and listed by,
// declared once for Capsomer's catalog. The table on /research/phages, its search and facets, and its counts all read
// this, so a field is described here and nowhere else. Pure: the route passes in the rows it read from D1. The page's
// markdown table (the twin, the search records, the invariants) is still written from the same rows by compile.mjs.

import { defineCatalog, parseCatalogParams, queryCatalog } from "capsomer/behavior/catalog";

import { HOSTS, PHAGES_PAGE_PATH, byYearThenName, phageSlug } from "./compile.mjs";

/** @typedef {import("./compile.mjs").Phage} Phage */

/** A host as a facet option and a cell read it, without the markdown emphasis the page's text carries. @param {string} key */
function hostLabel(key) {
  const host = /** @type {Record<string, { long: string }>} */ (HOSTS)[key];
  return host ? host.long.replaceAll("*", "") : key;
}

export const PHAGES = defineCatalog(
  /** @type {import("capsomer/behavior/catalog").CatalogDefinition<Phage>} */ ({
    id: "phages",
    noun: ["phage", "phages"],
    basePath: PHAGES_PAGE_PATH,
    itemKey: (p) => phageSlug(p.name),
    // Year, then name: what the page has always listed. The year's own comparison carries the name tie-break.
    defaultSort: "year",
    fields: [
      {
        key: "name",
        label: "Name",
        value: (p) => p.name,
        search: 3,
        sort: true,
        column: { header: "Phage" },
      },
      { key: "formerly", label: "Formerly", value: (p) => p.formerly, search: 1 },
      {
        key: "year",
        label: "Year",
        value: (p) => p.year,
        type: "number",
        sort: { compare: byYearThenName, labels: { asc: "oldest first", desc: "newest first" } },
        facet: { kind: "many", order: "alpha", limit: 6 },
        column: { header: "Year", align: "end" },
      },
      {
        key: "host",
        label: "Host",
        value: (p) => p.host,
        facet: { kind: "many", general: true, label: hostLabel },
        column: { header: "Host", drop: 1 },
      },
      {
        key: "county",
        label: "County",
        value: (p) => p.county,
        search: 1,
        facet: { kind: "many", order: "alpha" },
        column: { header: "County", drop: 2 },
      },
      {
        key: "phagesdb",
        label: "PhagesDB",
        value: (p) => p.phagesdb,
        column: { header: "PhagesDB", drop: 2 },
      },
      {
        key: "paper",
        label: "Genome paper",
        value: (p) => (p.paper ? "published" : null),
        facet: { kind: "one", label: () => "Published" },
        column: { header: "Paper", drop: 2 },
      },
    ],
  }),
);

/**
 * The page's state for an address.
 *
 * @param {URLSearchParams | string} params
 * @param {Phage[]} phages every phage
 */
export function phageListing(params, phages) {
  return queryCatalog(PHAGES, phages, parseCatalogParams(PHAGES, params));
}

app/lib/post-order.mjs.source:
// The order posts are listed in, newest first, as one rule for the two places that apply it: the D1 listing
// queries (app/db/posts.ts, newestFirstOrder) and the header's build-time list (scripts/lib/nav-data.mjs).
//
// 1. Publish instant, latest first.
// 2. Posts that share an instant: a series stays together and reads latest part first (the newest part of a
//    series is its newest post). A series sits among unrelated posts where its latest row would.
// 3. Otherwise the later row first. The database breaks that tie by row id; the build cannot see ids, so it
//    passes the slug, because rows are inserted in slug order (scripts/build-content.mjs).
//
// Concretely: sort by instant, then by the group key (the largest tie-break value among the posts sharing the
// instant and series, or the post's own value when it has no series), then by part, then by the tie-break
// value. That is a total order, which "part descending within a series, the tie-break otherwise" alone is not.

/**
 * @template {{ publishAt: string, series: string | null, part: number | null }} P
 * @param {P[]} posts
 * @param {(post: P) => string | number} tie the row id in a database, the slug in the build
 * @returns {P[]} a new array, newest first
 */
export function newestFirst(posts, tie) {
  /** @type {Map<string, string | number>} */
  const latest = new Map();
  const groupOf = (/** @type {P} */ p) => `${p.publishAt}\u0000${p.series}`;
  for (const p of posts) {
    if (p.series === null) continue;
    const seen = latest.get(groupOf(p));
    if (seen === undefined || tie(p) > seen) latest.set(groupOf(p), tie(p));
  }
  const key = (/** @type {P} */ p) =>
    p.series === null ? tie(p) : /** @type {string | number} */ (latest.get(groupOf(p)));
  const desc = (/** @type {string | number} */ a, /** @type {string | number} */ b) =>
    a === b ? 0 : a < b ? 1 : -1;
  return [...posts].sort(
    (a, b) =>
      desc(a.publishAt, b.publishAt) ||
      desc(key(a), key(b)) ||
      desc(a.part ?? 0, b.part ?? 0) ||
      desc(tie(a), tie(b)),
  );
}

app/lib/publications/parse.mjs.source:
// Reads a publication file (docs/PUBLICATIONS.md) into the front matter as written and the one body
// section it may carry, the extracted full text. Nothing here judges: validate.mjs does, so the check and
// the save tool read one parse.

import { matter } from "@drdustinedwards/site-helpers/matter";

import { yamlPlain } from "../yaml-plain.mjs";

export const PUBLICATIONS_DIR = "content/publications";

export function publicationPath(/** @type {string} */ slug) {
  return `${PUBLICATIONS_DIR}/${slug}.md`;
}

/** The only heading the body may carry. Everything after it is the PDF's extracted text. */
export const FULL_TEXT_HEADING = "## Full text";

const FULL_TEXT_LINE = /^## Full text[ \t]*$/m;

/**
 * @typedef {{ data: Record<string, unknown>, fullText: string | null, problems: string[] }} ParsedPublication
 */

/**
 * @param {{ file: string, raw: string }} input
 * @returns {ParsedPublication} `fullText` is null when the file has no Full text section, and a string (possibly empty) when it has.
 */
export function parsePublication({ file, raw }) {
  /** @type {string[]} */
  const problems = [];
  /** @type {Record<string, unknown>} */
  let data = {};
  let content = "";
  try {
    const parsed = matter(raw);
    data = /** @type {Record<string, unknown>} */ (yamlPlain(parsed.data));
    content = parsed.content;
  } catch (error) {
    problems.push(
      `${file}: the front matter does not parse: ${error instanceof Error ? error.message.split("\n")[0] : String(error)}`,
    );
    return { data, fullText: null, problems };
  }
  if (!raw.startsWith("---")) {
    problems.push(`${file}: the file must start with a --- front matter block`);
  }

  const heading = FULL_TEXT_LINE.exec(content);
  if (!heading) {
    if (content.trim() !== "") {
      problems.push(
        `${file}: the body carries text outside a "${FULL_TEXT_HEADING}" section. The abstract belongs in front matter, and the body holds only the PDF's extracted text under that heading.`,
      );
    }
    return { data, fullText: null, problems };
  }
  const before = content.slice(0, heading.index).trim();
  if (before !== "") {
    problems.push(
      `${file}: the body carries text before the "${FULL_TEXT_HEADING}" heading. The abstract belongs in front matter, and the body holds only the PDF's extracted text.`,
    );
  }
  const fullText = content.slice(heading.index + heading[0].length).trim();
  return { data, fullText, problems };
}

app/lib/publications/pdf-redirect.mjs.source:
// A paper's canonical URL is the slash form, because Google Scholar honors `citation_pdf_url` only when the
// PDF sits in the abstract page's own subdirectory. Not a move: the slashless form was never the page.

export const PUBLICATIONS_PREFIX = "/research/publications/";

/**
 * Skips anything with a dot so the PDF inside the directory still reaches the asset handler.
 *
 * @param {string} pathname
 * @returns {string | null} the canonical path, or null
 */
export function paperSlashTarget(pathname) {
  if (typeof pathname !== "string") return null;
  if (!pathname.startsWith(PUBLICATIONS_PREFIX)) return null;
  const rest = pathname.slice(PUBLICATIONS_PREFIX.length);
  if (rest.length === 0) return null;
  if (rest.includes("/")) return null;
  if (rest.includes(".")) return null;
  return `${pathname}/`;
}

app/kb/procedures/run.mjs.source:
// Run mode (docs/PROCEDURES.md "Run mode") is Capsomer's checklist run: what a bench run is, how its timers count,
// what the Markdown record says and how a stored run is read back, all in capsomer/behavior/checklist-run-model
// (extracted from this file). What stays here is the site's own: the JSON download as a Bioschemas LabProcess.

import { thing } from "@drdustinedwards/site-helpers/schema";
import { runRecord, when } from "capsomer/behavior/checklist-run-model";

import { SITE_ORIGIN } from "../../lib/site-origin.mjs";

/** The Bioschemas profile a run's download follows (docs/KNOWLEDGE-BASE.md, P4). */
const LAB_PROCESS_PROFILE = "https://bioschemas.org/profiles/LabProcess/0.1-DRAFT";

/**
 * The saved record as a plain object: what a download is, and what survives the browser. Capsomer's run record (only
 * what the person entered or did, with the procedure's own identity so the record says which version it followed),
 * with the checklist named `procedure`.
 *
 * It is also a Bioschemas LabProcess (P4): runs are private, so this download is the only place one is written. The
 * protocol it executes is named by the `@id` the procedure's page gives its LabProtocol, and its version.
 *
 * A step's `key` is unique in the procedure (its section and its number: numbering restarts in a section that starts
 * its own list), `number` is the one the page prints.
 *
 * @param {import("capsomer/behavior/checklist-run-model").Run} run
 * @param {import("capsomer/behavior/checklist-run-model").StepInfo[]} steps
 * @param {string} [origin] the site the run was made on
 */
export function labRunRecord(run, steps, origin = SITE_ORIGIN) {
  // A run made on a frozen version's page carries its /v/ address; the protocol's identity is its plain page.
  const page = run.path.replace(/\/v\/[^/]+$/, "");
  const { checklist, ...record } = runRecord(run, steps, "dustinedwards.info run");
  // The LabProcess node is Prelum's `thing`; the record's own fields follow it as they are, since a null scale or an empty
  // note is part of the saved record's format (RUN_VERSION), not a missing fact.
  return {
    ...thing("LabProcess", {
      "http://purl.org/dc/terms/conformsTo": { "@id": LAB_PROCESS_PROFILE },
      name: `Run of ${run.title}`,
      executesLabProtocol: {
        "@type": "LabProtocol",
        "@id": `${origin}${page}#procedure`,
        name: run.title,
        url: `${origin}${run.path}`,
        ...(run.version ? { version: run.version } : {}),
      },
      startTime: when(run.startedAt),
      ...(run.finishedAt !== null ? { endTime: when(run.finishedAt) } : {}),
      ...(run.note.trim() ? { description: run.note.trim() } : {}),
      ...(run.scale !== null
        ? { parameterValue: [{ "@type": "PropertyValue", name: "Scale", value: run.scale }] }
        : {}),
    }),
    record: record.record,
    format: record.format,
    procedure: checklist,
    scale: record.scale,
    startedAt: record.startedAt,
    finishedAt: record.finishedAt,
    note: record.note,
    steps: record.steps,
  };
}

app/kb/registry/align.mjs.source:
// Placing a primer on a reference, and the product a pair makes there (docs/REGISTRY.md): COMPUTED by the primer code in
// app/lib/primers.mjs (findSites, amplicons), whose tests hold it to hand-worked cases, and never copied from a paper or a
// database. A primer is looked for exactly first, then with one mismatch more at a time up to MAX_MISMATCHES, and the first
// level that finds it is the answer, with its mismatches reported. A primer that binds only with a mismatch is therefore
// shown with the mismatch, never silently absorbed, and a primer that binds nowhere within the limit has no placement.
//
// Coordinates are the accession's own: a slice of a chromosome (`NC_052532.1:76902320-76906237`) is reported on the
// chromosome, so a reader can check a position against the record at NCBI.

import { amplicons, findSites } from "../../lib/primers.mjs";
import { accessionPosition } from "./reference.mjs";
import { REFERENCES } from "./references.generated.mjs";

/** The most mismatches a primer may have against a reference and still be placed. A primer is 16 to 30 bases. */
export const MAX_MISMATCHES = 4;
/** A product longer than this is not a PCR product here; the registry's references are short or the primers sit close. */
const MAX_PRODUCT = 5000;

/**
 * @typedef {import("./reference.mjs").Reference} Reference
 * @typedef {{
 *   strand: "+" | "-",
 *   start: number,
 *   end: number,
 *   mismatches: number,
 *   mismatchPositions: number[],
 * }} Placed
 * A site in the accession's own coordinates; `mismatchPositions` are 1-based from the primer's 5' end.
 *
 * @typedef {{ reference: { id: string, accession: string, description: string }, sites: Placed[], mismatches: number }} Placement
 * @typedef {{
 *   length: number,
 *   start: number,
 *   end: number,
 *   forward: Placed,
 *   reverse: Placed,
 * }} Product
 */

/** The reference an id names, or null. @param {string} id @param {Record<string, Reference>} [references] */
function referenceFor(id, references = /** @type {any} */ (REFERENCES)) {
  const found = references[id];
  return found ? parseReferenceShape(found) : null;
}

/** The generated module's entries are already parsed; this keeps the type and refuses a malformed one. @param {any} entry @returns {Reference} */
function parseReferenceShape(entry) {
  if (typeof entry?.sequence !== "string" || typeof entry?.id !== "string")
    throw new Error("a reference in references.generated.mjs is malformed");
  return entry;
}

/** @param {Reference} reference @param {import("../../lib/primers.mjs").Site} site @returns {Placed} */
function placed(reference, site) {
  return {
    strand: site.strand,
    start: accessionPosition(reference, site.start),
    end: accessionPosition(reference, site.end),
    mismatches: site.mismatches,
    mismatchPositions: site.mismatchPositions,
  };
}

/**
 * Where a primer binds a reference: every site at the fewest mismatches that finds one.
 *
 * @param {string} sequence the primer, 5' to 3', A, C, G and T only
 * @param {string} referenceId
 * @param {Record<string, Reference>} [references]
 * @returns {Placement | null} null when the reference is unknown or the primer binds nowhere within MAX_MISMATCHES
 */
export function placePrimer(sequence, referenceId, references = /** @type {any} */ (REFERENCES)) {
  const reference = referenceFor(referenceId, references);
  if (!reference || !/^[ACGT]+$/.test(sequence)) return null;
  for (let mismatches = 0; mismatches <= MAX_MISMATCHES; mismatches += 1) {
    const sites = findSites(reference.sequence, sequence, { maxMismatches: mismatches }).filter(
      (s) => s.mismatches === mismatches,
    );
    if (sites.length > 0) {
      return {
        reference: {
          id: reference.id,
          accession: reference.accession,
          description: reference.description,
        },
        sites: sites.map((site) => placed(reference, site)),
        mismatches,
      };
    }
  }
  return null;
}

/**
 * The products a forward and a reverse primer make on a reference, each at the fewest mismatches either needs, shortest
 * first. A pair that makes none, or whose primers do not both place, has no product.
 *
 * @param {string} forward
 * @param {string} reverse
 * @param {string} referenceId
 * @param {Record<string, Reference>} [references]
 * @returns {{ reference: Placement["reference"], products: Product[] } | null}
 */
export function pairProducts(
  forward,
  reverse,
  referenceId,
  references = /** @type {any} */ (REFERENCES),
) {
  const reference = referenceFor(referenceId, references);
  const f = placePrimer(forward, referenceId, references);
  const r = placePrimer(reverse, referenceId, references);
  if (!reference || !f || !r) return null;
  const level = Math.max(f.mismatches, r.mismatches);
  const found = amplicons(reference.sequence, forward, reverse, {
    maxMismatches: level,
    maxLength: MAX_PRODUCT,
  })
    // Only the sites each primer was placed at: a product that used a worse site than the best is not the pair's.
    .filter((p) => p.forward.mismatches === f.mismatches && p.reverse.mismatches === r.mismatches)
    .map((p) => ({
      length: p.length,
      start: accessionPosition(reference, p.start),
      end: accessionPosition(reference, p.end),
      forward: placed(reference, p.forward),
      reverse: placed(reference, p.reverse),
    }))
    .sort((a, b) => a.length - b.length || a.start - b.start);
  return found.length === 0 ? null : { reference: f.reference, products: found };
}

/**
 * The products a protocol's primers make, computed, for the primer table of a page, sheet or twin: each set that holds one
 * forward and one reverse primer on one reference gives its pair's products, keyed by the id of both primers. A row with no
 * mate, no reference or no placement has no entry.
 *
 * @param {Array<{ id: string, set: string | null, direction: string | null, sequence: string | null, reference: string | null }>} rows
 * @returns {Map<string, { reference: Placement["reference"], products: Product[] }>}
 */
export function productsForRows(rows) {
  /** @type {Map<string, { reference: Placement["reference"], products: Product[] }>} */
  const out = new Map();
  const sets = new Set(rows.flatMap((row) => (row.set ? [row.set] : [])));
  for (const set of sets) {
    const inSet = rows.filter((row) => row.set === set);
    const forward = inSet.find((row) => row.direction === "forward");
    const reverse = inSet.find((row) => row.direction === "reverse");
    if (
      !forward?.sequence ||
      !reverse?.sequence ||
      !forward.reference ||
      forward.reference !== reverse.reference
    )
      continue;
    const pair = pairProducts(forward.sequence, reverse.sequence, forward.reference);
    if (pair) {
      out.set(forward.id, pair);
      out.set(reverse.id, pair);
    }
  }
  return out;
}

app/kb/registry/tm.mjs.source:
// A primer's melting temperature, computed from its sequence and never typed (a computable value is computed). The
// method and the conditions are stated on every page that shows a Tm, from the constants below, so a reader knows what
// the number means and a change of condition changes every page at once.
//
// METHOD. The unified nearest-neighbor model of SantaLucia (1998), Proc. Natl. Acad. Sci. USA 95:1460-1465, doi
// 10.1073/pnas.95.4.1460: the duplex's enthalpy and entropy are the sums of its dinucleotide steps plus an initiation
// term for each end, the entropy is corrected for the monovalent salt, and
//
//   Tm = 1000 x dH / (dS + R x ln(C)) - 273.15
//
// with dH in kcal/mol, dS in cal/(K x mol), R = 1.987 cal/(K x mol) and C the primer concentration. C is the primer
// concentration itself, not the total strand concentration over four, because in a PCR the primer is in large excess
// over the template (for strands at unequal concentration the term is C(excess) minus half of C(limiting), which is C when
// the template is far below the primer). A self-complementary primer also takes the symmetry term.
//
// CONDITIONS. 50 mM monovalent cation and 0.5 uM primer, with the template taken as far below the primer. They are the
// usual reporting defaults, not the conditions of any one reaction buffer (a master mix's own salt and Mg2+ shift the
// working Tm), so the figure is for comparing primers with each other. The page says so.
//
// A sequence with an ambiguity code or any base but A, C, G and T has no single Tm, so it has none here: null, never a
// guess. test/registry-tm.test.mjs holds this to Biopython's Bio.SeqUtils.MeltingTemp.Tm_NN (DNA_NN3, which carries the
// SantaLucia 1998 table, saltcorr 5, the template taken as zero).

/** The conditions every Tm on the site is computed under, stored once. */
export const TM_CONDITIONS = Object.freeze({
  /** Monovalent cation, mM. */
  sodiumMM: 50,
  /** Primer, nM. */
  primerNM: 500,
  method: "SantaLucia (1998) unified nearest-neighbor model",
  citation: "SantaLucia J Jr (1998), Proc Natl Acad Sci USA 95:1460-1465",
  doi: "10.1073/pnas.95.4.1460",
});

/** The shortest oligo the model is applied to; a Tm for fewer bases is not meaningful as a primer's. */
export const TM_MIN_LENGTH = 10;

const R = 1.987;

/** dH (kcal/mol) and dS (cal/(K x mol)) of each dinucleotide step, 5' to 3', SantaLucia 1998 Table 1. */
const STEP = /** @type {Record<string, [number, number]>} */ ({
  AA: [-7.9, -22.2],
  TT: [-7.9, -22.2],
  AT: [-7.2, -20.4],
  TA: [-7.2, -21.3],
  CA: [-8.5, -22.7],
  TG: [-8.5, -22.7],
  GT: [-8.4, -22.4],
  AC: [-8.4, -22.4],
  CT: [-7.8, -21.0],
  AG: [-7.8, -21.0],
  GA: [-8.2, -22.2],
  TC: [-8.2, -22.2],
  CG: [-10.6, -27.2],
  GC: [-9.8, -24.4],
  GG: [-8.0, -19.9],
  CC: [-8.0, -19.9],
});
/** Initiation at a terminal G-C pair and at a terminal A-T pair, added once per end. */
const INIT_GC = /** @type {[number, number]} */ ([0.1, -2.8]);
const INIT_AT = /** @type {[number, number]} */ ([2.3, 4.1]);
/** The symmetry correction for a self-complementary sequence (entropy only). */
const SYMMETRY_DS = -1.4;

const COMPLEMENT = /** @type {Record<string, string>} */ ({ A: "T", C: "G", G: "C", T: "A" });

/** @param {string} sequence */
function reverseComplement(sequence) {
  return sequence
    .split("")
    .reverse()
    .map((base) => COMPLEMENT[base])
    .join("");
}

/**
 * The Tm in degrees Celsius, unrounded, or null when the sequence is not an unambiguous DNA oligo of at least
 * TM_MIN_LENGTH bases.
 *
 * @param {string} sequence 5' to 3', upper case
 * @returns {number | null}
 */
export function primerTm(sequence) {
  if (!/^[ACGT]+$/.test(sequence) || sequence.length < TM_MIN_LENGTH) return null;
  let dH = 0;
  let dS = 0;
  for (let i = 0; i < sequence.length - 1; i += 1) {
    const [h, s] = /** @type {[number, number]} */ (STEP[sequence.slice(i, i + 2)]);
    dH += h;
    dS += s;
  }
  for (const end of [sequence[0], sequence[sequence.length - 1]]) {
    const [h, s] = end === "G" || end === "C" ? INIT_GC : INIT_AT;
    dH += h;
    dS += s;
  }
  const selfComplementary = sequence === reverseComplement(sequence);
  if (selfComplementary) dS += SYMMETRY_DS;
  // The salt correction of SantaLucia (1998) eq. 8, applied to the entropy: 0.368 per phosphate (N - 1) x ln [Na+].
  dS += 0.368 * (sequence.length - 1) * Math.log(TM_CONDITIONS.sodiumMM / 1000);
  const concentration = TM_CONDITIONS.primerNM * 1e-9;
  return (1000 * dH) / (dS + R * Math.log(concentration)) - 273.15;
}

/** The Tm to one decimal, or null where there is none. @param {string} sequence */
export function primerTmRounded(sequence) {
  const tm = primerTm(sequence);
  return tm === null ? null : Math.round(tm * 10) / 10;
}

/** NEB’s Tm calculator, which gives the annealing temperature for a particular polymerase. */
export const NEB_TM_CALCULATOR = Object.freeze({
  url: "https://tmcalculator.neb.com/",
  name: "NEB Tm Calculator",
});

/**
 * The sentence every page that shows a Tm carries: what the number is (an estimate, for comparing primers), what was
 * computed and under what conditions, from the one set of constants, so no page restates a number it could be wrong about.
 * It never calls the figure an annealing temperature; `annealingSentence` says where that comes from.
 */
export function tmStatement() {
  const { sodiumMM, primerNM, method, citation } = TM_CONDITIONS;
  return (
    `The melting temperature (Tm) is an estimate for comparing primers with each other, computed from the sequence with the ${method} ` +
    `(${citation}) at ${sodiumMM} mM monovalent cation and ${primerNM / 1000} µM primer. These are standard reporting ` +
    `conditions, not those of any one reaction buffer. A sequence with an ambiguity code has no single Tm and shows none.`
  );
}

/** The sentence's words up to the calculator, which a page links and the twin names. */
export const ANNEALING_LEAD =
  "The Tm estimate is not an annealing temperature. For the annealing temperature of a particular polymerase, use the";

/** Where the annealing temperature comes from: not from the Tm above. Plain text, with the calculator named. */
export function annealingSentence() {
  return `${ANNEALING_LEAD} ${NEB_TM_CALCULATOR.name} (${NEB_TM_CALCULATOR.url}).`;
}

app/lib/content/pipeline.mjs.source:
// The only markdown renderer, shared by the build and the Worker: if they could disagree, check:content
// would fail on content nobody edited. Runs in a Worker, so no node:fs. The pipeline is Prelum's
// (@drdustinedwards/site-helpers/render); this module holds what stays with the site: the frontmatter,
// the media rules and the post record.

import { ContentError, render } from "@drdustinedwards/site-helpers/render";
import { createHighlight } from "@drdustinedwards/site-helpers/render/highlight";
import { editorialPack } from "@drdustinedwards/site-helpers/render/packs";
import { isAllowedUrl } from "@drdustinedwards/site-helpers/render/url";
import { matter } from "@drdustinedwards/site-helpers/matter";
// Zod builds its parsers, and probes `new Function`, when a schema is created, so the flag goes first (site-runtime ./zod-jitless).
import "@dustinedwards/site-runtime/zod-jitless";
import { sha256Hex } from "@dustinedwards/site-runtime/encoding";
import { keyOfAddress } from "@dustinedwards/site-runtime/image";
import { z } from "zod";

// Mermaid drawings Prelum still emits as an <img> pair are sized from this file. The three hand-built
// diagrams are inlined and have no files; their sizes are merged in so Prelum does not warn that the
// drawing is missing, and the <img> is then replaced.
import diagramSizes from "../../../public/diagrams/sizes.json" with { type: "json" };
import { ASSET_PREFIX, classify, dimensionsFromKey } from "../media/classify.mjs";
import {
  inlineBlogDiagrams,
  inlineDiagramSizes,
  withoutInlinedDiagramRefs,
} from "./blog-diagrams.mjs";
import { makeChartData } from "./chart-data.mjs";
import { gitBlobSha } from "./hashes.mjs";
import { contentImage, images, mediaContentVersion } from "../media/images.mjs";
import { SLUG_MAX_LENGTH, SLUG_PATTERN, postPath } from "./slug.mjs";
import { SITE_ORIGIN } from "../site-origin.mjs";

import { readingTimeMinutes } from "./reading-time.mjs";
import { withBacklinks, withRelated } from "./corpus.mjs";
import { internalLinkSlug, isFurtherReadingUrl } from "./url-policy.mjs";

// Re-exported: build scripts, gates and tests import these from here, the renderer's one door.
export { ContentError, internalLinkSlug, isAllowedUrl, withBacklinks, withRelated };

// YAML turns an unquoted 2026-07-27 into a Date, so both spellings arrive here.
/** @param {unknown} value */
const asDateString = (value) =>
  value instanceof Date ? value.toISOString().slice(0, 10) : value;

/** @param {unknown} value */
const asDateTimeString = (value) =>
  value instanceof Date ? value.toISOString() : value;

const isoDate = z.preprocess(
  asDateString,
  z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "must be a YYYY-MM-DD date"),
);

const isoDateTime = z.preprocess(
  asDateTimeString,
  z
    .string()
    .refine((v) => !Number.isNaN(Date.parse(v)), "must be a parseable date-time"),
);

export { SLUG_ATTRIBUTE_PATTERN, SLUG_PATTERN, postPath } from "./slug.mjs";

export const frontmatterSchema = z.object({
  title: z.string().min(1, "must not be empty"),
  slug: z
    .string()
    .regex(SLUG_PATTERN, "must be lowercase kebab-case")
    .max(SLUG_MAX_LENGTH, `must be at most ${SLUG_MAX_LENGTH} characters`),
  date: isoDate,
  tags: z.array(z.string().min(1)).default([]),
  description: z.string().min(1, "must not be empty"),
  draft: z.boolean().default(false),
  publish_at: isoDateTime.optional(),
  cover: z
    .object({
      /**
       * The regex refuses protocol-relative paths; isAllowedUrl is the shared protocol check and
       * must be called, not reimplemented. Both are needed.
       */
      src: z
        .string()
        .regex(/^\/(?![/\\])/, "must be a site-absolute path, not //host or a full URL")
        .refine(isAllowedUrl, "protocol is not allowed (https, http, mailto or relative only)"),
      alt: z.string().min(1, "is required when cover is set"),
    })
    .optional(),
  featured: z.boolean().default(false),
  series: z.string().min(1).optional(),
  part: z.number().int().min(1, "must be 1 or greater").optional(),
  // Not `status`, which is the row's draft/published column. A closed set so readers learn it once.
  writing_status: z.enum(["notes", "draft", "in progress", "finished", "obsolete"]).optional(),
  assumed_audience: z.string().min(1).max(200).optional(),
  key_takeaways: z.array(z.string().min(1).max(300)).min(2).max(4).optional(),
  // isoDate because YAML parses a bare 2026-08-15 into a Date object.
  changelog: z
    .array(
      z.object({
        date: isoDate,
        note: z.string().min(1).max(300),
      }),
    )
    .min(1)
    .max(20)
    .optional(),
  further_reading: z
    .array(
      z.object({
        title: z.string().min(1, "must not be empty"),
        /**
         * isAllowedUrl is the SAME predicate the render layer uses (check:urls reads this phrase): z.url()
         * accepts javascript:, and rehypeUrlProtocols never sees frontmatter. Internal links are /writing/ paths, not absolute URLs, so they survive the origin change at cutover.
         */
        url: z
          .string()
          .refine(isFurtherReadingUrl, "must be an absolute http(s) URL or a /writing/ path")
          .refine(isAllowedUrl, "protocol is not allowed (https, http, mailto or relative only)"),
      }),
    )
    .default([]),
  og_title: z.string().min(1).optional(),
  og_description: z.string().min(1).optional(),
  // site-api's search fields (description is the one above): Carrel writes them under these shared names.
  searchTitle: z.string().min(1).optional(),
  image: z
    .string()
    .regex(/^\/(?![/\\])/, "must be a site-absolute path, not //host or a full URL")
    .refine(isAllowedUrl, "protocol is not allowed (https, http, mailto or relative only)")
    .optional(),
  imageAlt: z.string().min(1).optional(),
  canonical: z.string().url().refine((v) => /^https?:/.test(v), "must be an http(s) URL").optional(),
  noindex: z.boolean().default(false),
  /**
   * A date, not a timestamp: the build derives it from git and the editor cannot know the time of
   * the commit it is about to create, so only a date lets the two agree.
   */
  updated: isoDate.optional(),
  // Server-owned, stamped on first publish. renderPost deliberately keeps it out of the record.
  first_published: isoDate.optional(),
}).superRefine((value, ctx) => {
  if (value.series && value.part === undefined) {
    ctx.addIssue({ code: "custom", path: ["part"], message: "is required when series is set" });
  }
  if (value.part !== undefined && !value.series) {
    ctx.addIssue({ code: "custom", path: ["series"], message: "is required when part is set" });
  }
});

export { findWideDashes } from "@drdustinedwards/site-helpers/text";

export { readingTimeMinutes };

// Isolate-wide: one highlighter, the same for every request.
/** @type {ReturnType<typeof createHighlight> | null} */
let highlight = null;

/**
 * Injected: a Worker refuses WebAssembly.instantiate() on bytes, so it passes an instantiator over a
 * statically imported module. The engine is the same, so the HTML is byte-identical.
 *
 * @type {() => any}
 */
let wasmLoader = () => import("shiki/wasm");

/** @param {() => any} loader */
export function setWasmLoader(loader) {
  wasmLoader = loader;
  highlight = null;
}

function getHighlight() {
  highlight ??= createHighlight({ wasm: () => wasmLoader() });
  return highlight;
}

// The card key lives beside the card text it hashes, so a route can name a card without this renderer.
export { ogImageKey } from "./og-card-text.mjs";

/**
 * R2 objects are keyed after /media/ (site-runtime keyOfAddress: this site's own /media/ address, a size's suffix cut,
 * segments decoded and checked), static assets by their public path. Another host's /media/ address and an
 * unrecognized extension return null: neither is this site's file, and a page link is not a media citation.
 *
 * @param {string} raw
 * @returns {string | null}
 */
function mediaKeyOf(raw) {
  if (typeof raw !== "string" || raw.length === 0) return null;
  const key = keyOfAddress(raw, { origins: [SITE_ORIGIN] });
  if (key !== null) return key;

  let path = raw;
  const origin = path.match(/^(?:[a-z][a-z0-9+.-]*:)?\/\/[^/]+(\/.*)$/i);
  if (origin) path = origin[1] ?? path;
  // Query and fragment are not part of the key: ?w=320 is a transform request.
  path = path.split(/[?#]/)[0] ?? "";
  if (!path.startsWith("/") || path.startsWith("/media/")) return null;

  try {
    classify(path);
  } catch {
    return null;
  }
  return path;
}

/**
 * Only /media/ keys are responsive: static assets never pass through the transform route, so their
 * widths would 404. `sources` makes Prelum write a <picture>, AVIF then WebP; the <img> keeps the WebP
 * srcset. The link goes to the unsized original, which srcset never serves. A GIF's reduced-motion stills (site-runtime
 * 0.43, a source with `media`) are left out: this Prelum's <picture> writes no `media`, so a still would win for every
 * reader. The GIF stays animated, as before.
 *
 * @param {string} src
 */
function imageProps(src) {
  if (!src.startsWith("/media/")) return null;
  const key = src.slice("/media/".length);
  const { srcset, sizes, sources } = contentImage(src, dimensionsFromKey(key));
  // The original, versioned like its sizes (mediaContentVersion), so a link to it is never a stale copy either.
  const href = images.url(`/media/${key}`, { version: mediaContentVersion(key) });
  if (!srcset) return { href };
  return { srcSet: srcset, sizes, sources: sources.filter((s) => !s.media).map((s) => ({ type: s.type, srcSet: s.srcset })), href };
}

// assertSafe: Prelum's output scan runs on every render, the second check on chart markup and the rest of the page.
const SITE_OPTIONS = {
  media: { keyOf: mediaKeyOf, imageProps },
  assertSafe: true,
};

/**
 * The editorial pack for one render. `strictCharts` refuses a chart with no title or too many series (checklist E4),
 * so the publish names it before it goes live. `readChartData` reads a cited CSV from the
 * media library (chart-data.mjs); without it a `:::chart{src}` is refused, as Prelum does.
 *
 * @param {((key: string) => Promise<string | null>) | undefined} readChartData
 * @param {Set<string>} cited
 */
function packsFor(readChartData, cited) {
  return [
    editorialPack({
      assetPrefix: ASSET_PREFIX,
      strictCharts: true,
      diagramSizes: { ...diagramSizes, ...inlineDiagramSizes() },
      ...(readChartData ? { chartData: makeChartData(readChartData, cited) } : {}),
    }),
  ];
}

/**
 * @param {object} options
 * @param {string} options.file label used in error messages
 * @param {string} options.body markdown with frontmatter already stripped
 * @param {(src: string) => Promise<{ width: number, height: number }>} options.resolveImage
 * @param {(key: string) => Promise<string | null>} [options.readChartData] reads a chart's CSV from the media library
 */
export async function renderBody({ file, body, resolveImage, readChartData }) {
  /** @type {Set<string>} */
  const cited = new Set();
  const { html, toc, hasMath, diagrams, mediaRefs, blockedUrls } = await render({
    file,
    body,
    resolveImage,
    options: { ...SITE_OPTIONS, packs: packsFor(readChartData, cited), highlight: getHighlight() },
  });
  for (const key of cited) mediaRefs.push({ key, form: "other", detail: "chart data" });
  return {
    html: inlineBlogDiagrams(html),
    toc,
    hasMath,
    diagrams,
    mediaRefs: withoutInlinedDiagramRefs(mediaRefs),
    blockedUrls,
  };
}

/** @param {string} html */
function demoteFirstImage(html) {
  return html.replace(/<img\b[^>]*\bfetchpriority="high"[^>]*>/, (tag) =>
    tag.replace(' fetchpriority="high"', "").replace('loading="eager"', 'loading="lazy"'),
  );
}

/**
 * @param {object} options
 * @param {string} options.file path or label, used in error messages
 * @param {string} options.raw the whole file including frontmatter
 * @param {string} options.expectedSlug slug the filename implies
 * @param {(src: string) => Promise<{ width: number, height: number }>} options.resolveImage
 * @param {(key: string) => Promise<string | null>} [options.readChartData]
 */
export async function renderPost({ file, raw, expectedSlug, resolveImage, readChartData }) {
  const parsed = matter(raw);
  const result = frontmatterSchema.safeParse(parsed.data);
  if (!result.success) {
    const detail = result.error.issues
      .map((issue) => `${issue.path.join(".") || "(root)"} ${issue.message}`)
      .join("; ");
    throw new ContentError(file, `invalid frontmatter: ${detail}`);
  }
  const fm = result.data;

  if (fm.slug !== expectedSlug) {
    throw new ContentError(
      file,
      `slug "${fm.slug}" does not match the filename "${expectedSlug}"`,
    );
  }

  const rendered = await renderBody({
    file,
    body: parsed.content,
    resolveImage,
    readChartData,
  });
  const { toc, diagrams, mediaRefs, hasMath } = rendered;
  // The cover is the LCP where there is one, so the body's first image gives up Prelum's eager, high-priority pair:
  // two images marked high is the same as none.
  const html = fm.cover ? demoteFirstImage(rendered.html) : rendered.html;

  let cover = null;
  if (fm.cover) {
    const { width, height } = await resolveImage(fm.cover.src);
    cover = { src: fm.cover.src, alt: fm.cover.alt, width, height };
    // The body renderer never sees a frontmatter cover; without this it would be listed as unused.
    const coverKey = mediaKeyOf(fm.cover.src);
    if (coverKey) {
      mediaRefs.push({ key: coverKey, form: "frontmatter-cover", detail: "cover image" });
    }
  }

  const searchFields = {
    ...(fm.searchTitle ? { searchTitle: fm.searchTitle } : {}),
    ...(fm.image ? { image: fm.image, ...(fm.imageAlt ? { imageAlt: fm.imageAlt } : {}) } : {}),
    ...(fm.canonical ? { canonical: fm.canonical } : {}),
    ...(fm.noindex ? { noindex: true } : {}),
  };
  const imageKey = fm.image ? mediaKeyOf(fm.image) : null;
  if (imageKey) mediaRefs.push({ key: imageKey, form: "other", detail: "share image" });

  return {
    slug: fm.slug,
    title: fm.title,
    description: fm.description,
    date: fm.date,
    publishAt: fm.publish_at ?? `${fm.date}T00:00:00.000Z`,
    draft: fm.draft,
    tags: fm.tags,
    cover,
    featured: fm.featured,
    series: fm.series ?? null,
    part: fm.part ?? null,
    writingStatus: fm.writing_status ?? null,
    assumedAudience: fm.assumed_audience ?? null,
    keyTakeaways: fm.key_takeaways ?? null,
    changelog: fm.changelog ?? null,
    furtherReading: fm.further_reading,
    ogTitle: fm.og_title ?? null,
    ogDescription: fm.og_description ?? null,
    /** The search fields beside description, or null when the post sets none (the posts.search_fields column). */
    searchFields: Object.keys(searchFields).length > 0 ? searchFields : null,
    updated: fm.updated ?? null,
    readingTimeMinutes: readingTimeMinutes(parsed.content),
    // Never stored: it rides only so check:content can compare it with htmlHasMath.
    hasMath,
    toc,
    diagrams,
    mediaRefs,
    markdown: parsed.content,
    html,
    sourcePath: postPath(fm.slug),
    // Over the whole raw file, frontmatter included, because that is the blob git stores.
    sourceBlobSha: await gitBlobSha(raw),
    renderHash: await sha256Hex(html),
  };
}

app/lib/cv/markdown.mjs.source:
/**
 * The CV as markdown, from the same resolved entries the page renders (app/lib/cv/entries.mjs).
 * app/routes/cv[.md].ts serves it as the /cv.md twin (cvTwin), build:content compiles it for the search records,
 * and the PDF (app/lib/cv/pdf-html.mjs) is rendered from the same markdown, so the surfaces say the same thing.
 * Traditional order and no filtering: this is the version a committee reads start to finish.
 */

import { ORGANISM_PATTERN } from "../../data/organisms.ts";
import { contentPageMarkdownBody } from "../content-pages.mjs";
import { CV_PAGE, CV_PDF_PATH, formatDollars } from "./entries.mjs";
import { TYPES } from "./view.mjs";
// escapeMarkdown also escapes a colon before a letter: the pipeline reads `:word` as a directive and fails closed.
import { escapeMarkdown as esc } from "@drdustinedwards/site-helpers/text";

const OWNER_NAMES = new Set([
  "Dustin Edwards",
  "Dustin C. Edwards",
  "Dustin Cole Edwards",
  "D. Edwards",
]);

/** @param {string[]} authors */
function authorLine(authors) {
  return authors.map((name) => (OWNER_NAMES.has(name) ? `**${esc(name)}**` : esc(name))).join(", ");
}

/** @param {import("./entries.mjs").CvEntry} e */
function paperItem(e) {
  const p = e.paper;
  if (!p) throw new Error(`cv markdown: ${e.id} is a publication with no paper`);
  const end = /[.?!]$/.test(e.title) ? "" : ".";
  const links = [];
  if (p.doi) links.push(`[doi:${esc(p.doi)}](https://doi.org/${p.doi})`);
  if (p.pmid) links.push(`[PubMed ${p.pmid}](https://pubmed.ncbi.nlm.nih.gov/${p.pmid}/)`);
  // Genus and species italic, as the paper pages set them (app/lib/scientific-names.tsx).
  const title = esc(e.title).replace(ORGANISM_PATTERN, (name) => `*${name}*`);
  return `${authorLine(p.authors)}. ${e.year}. ${title}${end} *${esc(p.venue)}*.${links.length ? ` ${links.join(", ")}` : ""}`;
}

/** @param {import("./entries.mjs").CvEntry} e */
function lineItem(e) {
  const lead = e.when ? `**${e.when}** ` : "";
  switch (e.type) {
    case "grant": {
      const parts = [formatDollars(e.amount ?? 0), e.title, ...e.meta, ...(e.note ? [e.note] : [])];
      return `${lead}${esc(parts.join(", "))}`;
    }
    case "course":
      return esc(`${e.title}, ${e.meta.join(", ")}`);
    case "talk":
      return `${lead}${esc(e.title)}. ${esc(e.meta.join(". "))}`;
    default: {
      const rest = e.meta.filter(Boolean);
      return `${lead}${esc(e.title)}${rest.length ? `. ${esc(rest.join(". "))}` : ""}`;
    }
  }
}

/**
 * @param {import("./entries.mjs").Cv} CV the resolved CV (buildCv)
 * @param {{ pdf?: boolean }} [options] the PDF leaves out the opening lines, which it sets as a letterhead
 * @returns {string} markdown body, no frontmatter
 */
export function cvMarkdownBody(CV, options = {}) {
  const { person, entries, presentations } = CV;
  const out = [];
  // The PDF sets its own letterhead (app/lib/cv/pdf-html.mjs), so it starts at the first section.
  if (!options.pdf) {
    out.push(
      `${person.name}, ${person.degree} ${person.title}, ${person.department}, ${esc(person.org)}.`,
    );
    out.push("");
    out.push(
      `This is the ${CV.edition} CV. The same entries are at [/cv](/cv), where they can be filtered, and as a [PDF](${CV_PDF_PATH}). Each paper also has its own page under [Publications](/research/publications).`,
    );
  }

  for (const [type, , plural] of TYPES) {
    const list = entries.filter((e) => e.type === type);
    if (list.length === 0) continue;
    out.push(...(out.length ? [""] : []), `## ${plural}`);
    if (type === "talk") {
      out.push(
        "",
        `The CV lists ${presentations.international} international and ${presentations.national} national and regional presentations, ${presentations.from}-${presentations.to}, most of them posters and talks given by students with Dustin as senior author. Invited talks, seminars and roundtables where Dustin is the lead or only author:`,
      );
    }
    if (type === "mentoring") {
      out.push("", "Shown as counts; the CV names each student.");
    }
    if (type === "grant") {
      const total = list.reduce((sum, e) => sum + (e.amount ?? 0), 0);
      out.push(
        "",
        `${list.length} awards totaling ${formatDollars(total)}, newest first. Where a student shares an award, this says "with a student researcher" instead of a name.`,
      );
    }

    /** @type {Map<string, typeof list>} */
    const sections = new Map();
    for (const e of list) {
      const key = e.section ?? "";
      if (!sections.has(key)) sections.set(key, []);
      sections.get(key)?.push(e);
    }
    for (const [section, items] of sections) {
      if (section) out.push("", `### ${esc(section)}`);
      if (type === "publication") {
        out.push("");
        items.forEach((e, i) => out.push(`${i + 1}. ${paperItem(e)}`));
        continue;
      }
      let listOpen = false;
      for (const e of items) {
        if (e.duties.length === 0) {
          if (!listOpen) out.push("");
          listOpen = true;
          out.push(`- ${lineItem(e)}`);
          continue;
        }
        listOpen = false;
        out.push("", `#### ${esc(`${e.when}: ${e.title}`)}`, "", `${esc(e.meta.join(". "))}.`);
        for (const duty of e.duties) {
          out.push("", `${esc(duty.heading)}:`, "");
          for (const item of duty.items) out.push(`- ${esc(item)}`);
        }
      }
    }
  }

  return `${out.join("\n")}\n`;
}

/** The whole source file build:content reads for /cv, frontmatter included. */
/** @param {import("./entries.mjs").Cv} CV the resolved CV (buildCv) */
export function cvMarkdownDocument(CV) {
  const fm = [
    "---",
    `path: ${CV_PAGE.path}`,
    `title: ${JSON.stringify(CV_PAGE.title)}`,
    `seo_title: ${JSON.stringify(CV_PAGE.seoTitle)}`,
    `description: ${JSON.stringify(CV_PAGE.description)}`,
    "schema_type: WebPage",
    "---",
    "",
  ].join("\n");
  return `${fm}${cvMarkdownBody(CV)}`;
}

/**
 * The twin a machine reads at /cv.md: the title, then the body, as every page's twin is made
 * (contentPageMarkdownBody), so the CV answers as the other pages do.
 *
 * @param {import("./entries.mjs").Cv} CV the resolved CV (buildCv)
 */
export function cvTwin(CV) {
  return contentPageMarkdownBody({
    path: CV_PAGE.path,
    title: CV_PAGE.title,
    markdown: cvMarkdownBody(CV),
  });
}

