/**
 * A derived index against its source: the sizes, what it lacks and what it holds beyond the source,
 * each sorted. Kept apart so a missing key and an extra one cannot cancel out in a count.
 *
 * @param {Set<string>} expected
 * @param {Set<string>} present
 */
export function setDrift(expected, present) {
  return {
    expected: expected.size,
    present: present.size,
    missing: [...expected].filter((k) => !present.has(k)).sort(),
    extra: [...present].filter((k) => !expected.has(k)).sort(),
  };
}

/**
 * The Ask index holds one item per row its query returns (AI Search adds and removes them itself on each sync), so
 * the two counts are the comparison, and a row the index refused (too large, empty) fails it too.
 *
 * @param {{ expected: number, present: number, failed: number, indexing: number }} status
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function askDriftVerdict(status) {
  if (status.expected === status.present && status.failed === 0) {
    return {
      ok: true,
      detail: `Ask index agrees with D1: ${status.expected} expected, ${status.present} present.`,
    };
  }
  return {
    ok: false,
    detail:
      `Ask index drift: ${status.expected} expected, ${status.present} present, ` +
      `${status.failed} refused, ${status.indexing} indexing. A sync is asked for within the minute; ` +
      `a refused row is named in the AI Search job logs.`,
    counts: { expected: status.expected, present: status.present },
  };
}

/**
 * Both directions summed, since they can cancel in a count comparison while both are true. Here R2 is
 * the truth and D1 the projection.
 *
 * @param {{ expected: number, present: number, missing: string[], extra: string[] }} status
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function mediaDriftVerdict(status) {
  const drift = status.missing.length + status.extra.length;
  if (drift === 0) {
    return {
      ok: true,
      detail: `Site file index agrees with OG and public/: ${status.expected} expected, ${status.present} present.`,
    };
  }
  return {
    ok: false,
    detail:
      `Site file index drift ${drift}: ${status.missing.length} missing, ` +
      `${status.extra.length} extra, ${status.expected} expected, ` +
      `${status.present} present. Repair with sync_media on the operator API, ` +
      `or Rebuild the site file index on /admin/tools.`,
    counts: { expected: status.expected, present: status.present },
  };
}

/**
 * Shared with the sync_posts repair, so what the check calls drift and what the repair repairs agree.
 *
 *   changed  a slug present on both sides whose blob sha differs: the file
 *            moved and the row has not followed (or a row's provenance was
 *            corrupted, which repairs identically).
 *   unrowed  a file with no row: a post committed from a clone that no sync
 *            has landed yet, or a lost row.
 *   unfiled  a row with no file: a post deleted from the repository whose
 *            rows outlived it.
 *
 * @param {Array<{ slug: string, sha: string }>} files from the Contents
 *   directory listing, blob sha per markdown file
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @returns {{ changed: string[], unrowed: string[], unfiled: string[] }}
 */
export function contentDriftCompare(files, rows) {
  const rowBySlug = new Map(rows.map((r) => [r.slug, r]));
  const fileSlugs = new Set(files.map((f) => f.slug));

  const changed = files
    .filter((f) => {
      const row = rowBySlug.get(f.slug);
      return row !== undefined && row.source_blob_sha !== f.sha;
    })
    .map((f) => f.slug)
    .sort();
  const unrowed = files
    .filter((f) => !rowBySlug.has(f.slug))
    .map((f) => f.slug)
    .sort();
  const unfiled = rows
    .filter((r) => !fileSlugs.has(r.slug))
    .map((r) => r.slug)
    .sort();

  return { changed, unrowed, unfiled };
}

/**
 * present counts rows in full agreement, so equal totals with one sha changed still read as drift.
 *
 * @param {Array<{ slug: string, sha: string }>} files
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function contentDriftVerdict(files, rows) {
  return sourceDriftVerdict(files, rows, { label: "Content", noun: "post", tool: "sync_posts" });
}

/**
 * The same comparison for the procedure files and the procedures table, so what counts as drift is one
 * rule for both.
 *
 * @param {Array<{ slug: string, sha: string }>} files
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function procedureDriftVerdict(files, rows) {
  return sourceDriftVerdict(files, rows, {
    label: "Procedure",
    noun: "procedure",
    tool: "sync_procedures",
  });
}

/**
 * The same comparison for the dictionary entry files and the dictionary_entries table.
 *
 * @param {Array<{ slug: string, sha: string }>} files
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function dictionaryDriftVerdict(files, rows) {
  return sourceDriftVerdict(files, rows, {
    label: "Dictionary",
    noun: "dictionary entry",
    tool: "sync_dictionary",
  });
}

/**
 * The same comparison for the page files and the pages table.
 *
 * @param {Array<{ slug: string, sha: string }>} files
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function pageDriftVerdict(files, rows) {
  return sourceDriftVerdict(files, rows, { label: "Page", noun: "page", tool: "sync_pages" });
}

/**
 * The same comparison for the CV files and the cv table.
 *
 * @param {Array<{ slug: string, sha: string }>} files
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function cvDriftVerdict(files, rows) {
  return sourceDriftVerdict(files, rows, { label: "CV", noun: "CV", tool: "sync_cv" });
}

/**
 * The CV's PDF against the CV D1 holds now and the deployed print document: the stored object's stamp (custom
 * metadata, cvPdfStamp) against the stamp of the data and print document. `stored` is null when there is no object and "" when there is one that carries no
 * fingerprint (neither is current). Derived store against its source, as the others, repaired by sync_cv_pdf.
 *
 * @param {{ stored: string | null, expected: string }} sides
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function cvPdfDriftVerdict({ stored, expected }) {
  if (stored === expected) {
    return {
      ok: true,
      detail: `The stored CV PDF was drawn from the CV data D1 holds now and the deployed print document (${expected}).`,
    };
  }
  const what =
    stored === null
      ? "there is no stored CV PDF"
      : stored === ""
        ? "the stored CV PDF carries no fingerprint"
        : `the stored CV PDF was drawn from ${stored}`;
  return {
    ok: false,
    detail: `CV PDF drift 1: ${what}, and D1's CV with the deployed print document is ${expected}. Repair with sync_cv_pdf.`,
    counts: { expected: 1, present: 0 },
  };
}

/**
 * The same comparison for the publication files and the publications table.
 *
 * @param {Array<{ slug: string, sha: string }>} files
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function publicationDriftVerdict(files, rows) {
  return sourceDriftVerdict(files, rows, {
    label: "Publication",
    noun: "publication",
    tool: "sync_publications",
  });
}

/**
 * The same comparison for the roster files and the roster table.
 *
 * @param {Array<{ slug: string, sha: string }>} files
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function rosterDriftVerdict(files, rows) {
  return sourceDriftVerdict(files, rows, { label: "Roster", noun: "cohort", tool: "sync_roster" });
}

/**
 * The same comparison for the phage files and the phages table.
 *
 * @param {Array<{ slug: string, sha: string }>} files
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function phageDriftVerdict(files, rows) {
  return sourceDriftVerdict(files, rows, { label: "Phage", noun: "phage", tool: "sync_phages" });
}

/**
 * The same comparison for the registry files and the registry table. An item is read by its address, `<kind>/<id>`.
 *
 * @param {Array<{ slug: string, sha: string }>} files
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function registryDriftVerdict(files, rows) {
  return sourceDriftVerdict(files, rows, {
    label: "Registry",
    noun: "registry item",
    tool: "sync_registry",
  });
}

/**
 * The same comparison for content/llms.txt and the settings row /llms.txt is served from: one file, one row.
 *
 * @param {Array<{ slug: string, sha: string }>} files
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function llmsDriftVerdict(files, rows) {
  return sourceDriftVerdict(files, rows, {
    label: "llms.txt",
    noun: "llms.txt",
    tool: "sync_llms",
  });
}

/**
 * @param {Array<{ slug: string, sha: string }>} files
 * @param {Array<{ slug: string, source_blob_sha: string | null }>} rows
 * @param {{ label: string, noun: string, tool: string }} words
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
function sourceDriftVerdict(files, rows, { label, noun, tool }) {
  const { changed, unrowed, unfiled } = contentDriftCompare(files, rows);
  const drift = changed.length + unrowed.length + unfiled.length;
  if (drift === 0) {
    return {
      ok: true,
      detail: `D1 agrees with the repository: ${files.length} ${noun} file(s), every blob sha matched by its row.`,
    };
  }
  return {
    ok: false,
    detail:
      `${label} drift ${drift}: ${changed.length} sha-changed, ${unrowed.length} ` +
      `file(s) with no row, ${unfiled.length} row(s) with no file, against ` +
      `${files.length} ${noun} file(s). Repair with ${tool} on the operator API.`,
    counts: { expected: files.length, present: files.length - changed.length - unrowed.length },
  };
}

/**
 * Counted on the _docsize shadows: COUNT(*) on an external-content fts5 table reads through to its
 * content table and never fails. A count that cannot be read FAILS rather than comparing undefined.
 *
 * @param {Record<string, unknown>} counts
 * @returns {{ ok: boolean, detail: string, counts?: { expected: number, present: number } }}
 */
export function ftsEqualityVerdict(counts) {
  const NAMES = ["posts", "postsFts", "docs", "identity", "prose"];

  const unreadable = NAMES.filter((n) => !Number.isInteger(counts[n]) || Number(counts[n]) < 0);
  if (unreadable.length > 0) {
    return {
      ok: false,
      detail:
        `FTS counts unreadable: ${unreadable.join(", ")} ` +
        `${unreadable.length === 1 ? "is" : "are"} missing or not a whole number. ` +
        `A count that cannot be read is not a passing check.`,
    };
  }

  const posts = Number(counts.posts);
  const postsFts = Number(counts.postsFts);
  const docs = Number(counts.docs);
  const identity = Number(counts.identity);
  const prose = Number(counts.prose);

  const broken = [];
  if (posts !== postsFts) broken.push(`posts=${posts} but posts_fts_docsize=${postsFts}`);
  if (identity !== docs || prose !== docs) {
    broken.push(
      `search_docs=${docs} but search_identity_docsize=${identity} and ` +
        `search_prose_docsize=${prose}`,
    );
  }

  if (broken.length === 0) {
    return {
      ok: true,
      detail:
        `FTS indexes agree: posts=${posts}=posts_fts_docsize, ` +
        `search_docs=${docs}=identity=prose.`,
    };
  }

  return {
    ok: false,
    detail:
      `FTS index drift: ${broken.join("; ")}. ` +
      `Rebuild with INSERT INTO <index>(<index>) VALUES('rebuild'). ` +
      `Do NOT DELETE FROM either index; that corrupts it further.`,
    // The first disagreeing pair only; the full five are in detail, which stays off the wire.
    counts:
      posts !== postsFts
        ? { expected: posts, present: postsFts }
        : { expected: docs, present: identity !== docs ? identity : prose },
  };
}

/** Measured: ask-index-drift maxed at 2332 ms over 12 samples, so 3 s clears it without false alarms. */
export const CHECK_TIMEOUT_MS = 3000;

