// Its own module because ogImageKey must hash the same clamped strings the card draws, and because a
// route names a page's card through it without importing the markdown renderer. Characters stand in
// for width, so every number here was measured off rendered cards.

import { CARD_DESCRIPTION_MAX, cardKey, clampTitle } from "@dustinedwards/site-runtime/share-card";
import { formatDate } from "capsomer/behavior/time";
import { ASSET_PREFIX } from "../media/classify.mjs";

/**
 * @param {string | null | undefined} title
 * @returns {string}
 */
export function cardTitle(title) {
  return clampTitle(title);
}

/**
 * @param {string | null | undefined} description
 * @returns {string}
 */
export function cardDescription(description) {
  return clampTitle(description, CARD_DESCRIPTION_MAX);
}

// Bump on any card template change: the key hashes only the card's inputs, and an immutable cache
// ignores a restyled PNG under an unchanged key forever.
const OG_TEMPLATE_VERSION = 7;

/**
 * Hashes exactly what the card draws, AS DRAWN (through cardTitle, cardDescription, formatDate), so
 * the key changes when the picture would and never otherwise. FNV-1a: identical in Node and a Worker,
 * and this is a cache-busting key, not a security boundary.
 *
 * @param {{
 *   slug: string,
 *   title: string,
 *   description?: string | null,
 *   publishAt?: string | null,
 * }} post
 */
export function ogImageKey(post) {
  return cardKey({
    slug: post.slug,
    parts: [cardTitle(post.title), cardDescription(post.description), formatDate(post.publishAt)],
    version: OG_TEMPLATE_VERSION,
    prefix: `og/${ASSET_PREFIX}`,
  });
}

app/lib/cv/pdf-html.mjs.source:
// The CV's print document and the numbers the PDF is stamped with, shared by the two renderers: the Worker
// (app/lib/cv/pdf.server.ts, Browser Run's quickAction after each CV save) and the offline script
// (scripts/build-cv-pdf.mjs, headless Chrome through puppeteer). One copy of the HTML, so the two cannot draw
// different documents. Nothing here needs a browser, a filesystem or a Worker binding: the markdown pipeline and
// the fonts come in as arguments, because the Worker reads them one way and the script another.

import { escapeHtml } from "@dustinedwards/site-runtime/html";

import { sha256Hex, toBase64 } from "@dustinedwards/site-runtime/encoding";
import { OWNER_ORCID, SITE_ORIGIN } from "../seo.ts";
import { cvMarkdownBody, cvMarkdownDocument } from "./markdown.mjs";

/** The words the PDF's last line carries before the fingerprint. */
export const FINGERPRINT_LABEL = "CV data";

/**
 * Eight hex characters of the twin's source (SHA-256, through Web Crypto so the Worker and Node compute the same).
 * The PDF prints it, and the stored object carries it as custom metadata, so a PDF rendered from other data than
 * the CV now holds is a difference two sides can compare.
 *
 * @param {import("./entries.mjs").Cv} CV
 * @returns {Promise<string>}
 */
export async function cvFingerprint(CV) {
  return (await sha256Hex(cvMarkdownDocument(CV))).slice(0, 8);
}

/**
 * What the stored PDF is stamped with: the data's fingerprint and eight hex characters of the print document (its
 * stylesheet, its footer, the page options and the font files), so a deploy that changes only how the PDF
 * is drawn leaves the stored one stale, and the drift check and sync_cv_pdf render it again. A font recut under the
 * same file name is the one change this cannot see; a recut gets a new name.
 *
 * @param {import("./entries.mjs").Cv} CV
 * @returns {Promise<string>}
 */
export async function cvPdfStamp(CV) {
  const print = JSON.stringify([PRINT_CSS, cvFooterCss(CV), cvPdfOptions(), PDF_FONTS]);
  return `${await cvFingerprint(CV)}-${(await sha256Hex(print)).slice(0, 8)}`;
}

/**
 * The running footer, in the page's margin boxes (CSS Paged Media). Not Chrome's footerTemplate: a template is
 * drawn without the document's web fonts, so it fell back to the system's Arial (Liberation Sans in Browser Run)
 * whatever face it named. A margin box is drawn with the document's own fonts.
 *
 * @param {import("./entries.mjs").Cv} CV
 */
function cvFooterCss(CV) {
  const footer = `${CV.person.name}, Curriculum Vitae, ${CV.edition}`;
  const text = `"${footer.replace(/[\\"]/g, "\\$&").replace(/</g, "\\3c ")}"`;
  const box = 'font-family: "Inter", Arial, sans-serif; font-size: 7.5pt; color: #6a6159;';
  return `@page { @bottom-left { content: ${text}; ${box} } @bottom-right { content: counter(page) " of " counter(pages); ${box} } }`;
}

/** @param {string} family @param {Uint8Array} bytes @param {string} style */
export function fontFaceRule(family, bytes, style) {
  return `@font-face{font-family:"${family}";src:url(data:font/woff2;base64,${toBase64(bytes)}) format("woff2");font-style:${style};font-weight:100 900;}`;
}

/** The three faces the print document uses: file name, family and style, for whoever reads them. */
export const PDF_FONTS = /** @type {const} */ ([
  { file: "source-serif-4-latin-normal.woff2", family: "Source Serif 4", style: "normal" },
  { file: "source-serif-4-latin-italic.woff2", family: "Source Serif 4", style: "italic" },
  { file: "inter-latin-wght-normal.woff2", family: "Inter", style: "normal" },
]);

const PRINT_CSS = `
@page { size: Letter; margin: 0.8in 0.85in 0.85in; }
html { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
body { margin: 0; color: #1f1a17; font-family: "Source Serif 4", Georgia, serif; font-size: 10.5pt; line-height: 1.42; }
a { color: inherit; text-decoration: none; }
.letterhead { border-bottom: 1.5pt solid #4f2d7f; padding-bottom: 10pt; margin-bottom: 4pt; }
.letterhead h1 { margin: 0; color: #4f2d7f; font-size: 24pt; font-weight: 650; letter-spacing: -0.01em; line-height: 1.1; }
.letterhead p { margin: 4pt 0 0; font-family: "Inter", Arial, sans-serif; font-size: 9pt; color: #4a423b; line-height: 1.45; }
.letterhead .edition { text-transform: uppercase; letter-spacing: 0.08em; font-size: 7.5pt; font-weight: 600; color: #6a6159; margin: 0 0 6pt; }
h2 { margin: 16pt 0 6pt; padding-bottom: 3pt; border-bottom: 0.6pt solid #b9ada0; color: #4f2d7f; font-size: 13pt; font-weight: 650; break-after: avoid; }
h3 { margin: 10pt 0 4pt; font-family: "Inter", Arial, sans-serif; font-size: 8pt; font-weight: 650; letter-spacing: 0.06em; text-transform: uppercase; color: #4a423b; break-after: avoid; }
h4 { margin: 10pt 0 2pt; font-size: 10.5pt; font-weight: 650; break-after: avoid; }
.heading-anchor { display: none; }
p { margin: 3pt 0; }
ul, ol { margin: 3pt 0; padding-left: 16pt; }
li { margin: 0 0 3.5pt; break-inside: avoid; }
ul li::marker { color: #8a7d6e; }
ul:has(> li > strong:first-child) { padding-left: 0; }
ul > li:has(> strong:first-child) { list-style: none; padding-left: 6.4em; text-indent: -6.4em; }
ul > li > strong:first-child { display: inline-block; width: 6.4em; text-indent: 0; font-family: "Inter", Arial, sans-serif; font-size: 8.5pt; font-weight: 600; color: #4a423b; }
ol li::marker { color: #6a6159; font-family: "Inter", Arial, sans-serif; font-size: 8.5pt; }
strong { font-weight: 650; }
em { font-style: italic; }
.fingerprint { margin-top: 18pt; font-family: "Inter", Arial, sans-serif; font-size: 7.5pt; color: #6a6159; }
`;

/**
 * The print document for a resolved CV: the letterhead, the twin's markdown through the site's pipeline, the
 * fonts inlined, and the fingerprint. A function of the CV alone, so whatever holds a CV (the script from the
 * files, the Worker from D1) renders the same page.
 *
 * @param {import("./entries.mjs").Cv} CV
 * @param {{ renderBody: (input: { file: string, body: string, resolveImage: (src: string) => Promise<never> }) => Promise<{ html: string, blockedUrls: Array<{ url: string }> }>, fontCss: string }} deps
 *   the site's markdown pipeline, and the `@font-face` rules for PDF_FONTS
 */
export async function renderCvHtml(CV, { renderBody, fontCss }) {
  const rendered = await renderBody({
    file: "content/cv",
    body: cvMarkdownBody(CV, { pdf: true }),
    resolveImage: async (src) => {
      throw new Error(`the CV references an image (${src}) and its PDF has no image pipeline.`);
    },
  });
  if (rendered.blockedUrls.length > 0) {
    throw new Error(
      `the CV carries link(s) the URL allowlist refused: ${rendered.blockedUrls.map((b) => b.url).join(", ")}`,
    );
  }
  const { person } = CV;
  const host = new URL(SITE_ORIGIN).host;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${escapeHtml(`${person.name}, Curriculum Vitae`)}</title>
<style>${fontCss}${PRINT_CSS}${cvFooterCss(CV)}</style></head><body>
<header class="letterhead">
<p class="edition">Curriculum Vitae · ${escapeHtml(CV.edition)}</p>
<h1>${escapeHtml(`${person.name}, ${person.degree}`)}</h1>
<p>${escapeHtml(`${person.title}, ${person.department}, ${person.org}`)}</p>
<p><a href="${SITE_ORIGIN}/cv">${escapeHtml(`${host}/cv`)}</a> · <a href="${OWNER_ORCID}">ORCID ${OWNER_ORCID.split("/").pop()}</a></p>
</header>
${rendered.html}
<p class="fingerprint">Generated from the same data as ${escapeHtml(`${host}/cv`)}, where every entry can be searched and filtered. ${FINGERPRINT_LABEL} ${await cvFingerprint(CV)}.</p>
</body></html>`;
}

/**
 * The page.pdf() options, in the form puppeteer and Browser Run's quickAction("pdf") both read (every field is in
 * quickAction's documented pdfOptions). `format` is lower case, which both accept.
 */
export function cvPdfOptions() {
  return {
    format: /** @type {"letter"} */ ("letter"),
    printBackground: true,
    preferCSSPageSize: true,
    tagged: true,
    outline: true,
  };
}

app/lib/media/images.mjs.source:
import { defineImages, pictureProps } from "@dustinedwards/site-runtime/image";

import { digestFromKey, dimensionsFromKey } from "./classify.mjs";

// CSS pixels, never physical: the browser multiplies by the device pixel ratio itself. The 44rem prose column
// is about 704 CSS px.
const CONTENT_SIZES = "(min-width: 46rem) 704px, calc(100vw - 2rem)";

/**
 * Every way the site shows an image from /media, and so the route's closed width set (site-runtime ./image):
 * the set is CLOSED because the Images binding bills each unique transform, and the pipeline and the route
 * share it, so a width the page advertises is never a 400 mid-article. `breakpoints` keeps the widths the
 * site served before the move (640, 1024, 1408), so cached pages and feeds that link `?w=1024` still work;
 * the content use then serves 640, 704, 1024 and 1408. `tile` is the admin grid and `portrait` the about photo
 * (both 320 and 640), scaled, never cropped. `shareImages` adds the 1200-wide crops a post's Article JSON-LD names
 * (articleCrops).
 */
export const images = defineImages({
  shareImages: true,
  breakpoints: [640, 1024, 1408],
  uses: {
    content: { layout: "constrained", width: 704, sizes: CONTENT_SIZES },
    tile: { layout: "fixed", width: 320 },
    portrait: { layout: "fixed", width: 320, sizes: "(min-width: 46rem) 14rem, 11rem" },
  },
});

/**
 * A /media file's version, which its size URLs carry (`v=`, site-runtime ./image), so a file whose bytes change is a new
 * URL and none is cached stale for the year a size is kept: the bytes' sha256 where the caller read the row (a replace
 * or a turn in place writes it), else the digest its content key carries (dustin-edwards-<name>-<digest>-<w>x<h>.<ext>).
 * Rendered bodies, covers and procedure photos use the key's digest, which the Node build can read too, so a post
 * renders the same in the Worker and in the build; a file replaced in place keeps that address in them until the post
 * is rendered again from a row that holds its new hash. Not site-api's `mediaVersion` (`r` and the index row's rev, the
 * version its media writes are checked against): this one is the bytes' digest, which a size URL needs and the build can read.
 *
 * @param {string} keyOrPath a /media key or path
 * @param {string | null} [sha256]
 */
export function mediaContentVersion(keyOrPath, sha256 = null) {
  return sha256 ?? digestFromKey(keyOrPath);
}

/**
 * Responsive attributes for one /media image in the prose column. A key that does not carry its size gets the
 * ladder anyway, as before the move: the route scales down and never up, so a smaller original is served at its
 * own size.
 *
 * @param {string} src a `/media/` path
 * @param {{ width: number, height: number } | null} dimensions
 */
export function contentImage(src, dimensions) {
  const { width, height } = dimensions ?? { width: 2816, height: 2816 };
  return images.attributes({ src, width, height, version: mediaContentVersion(src) }, "content");
}

/**
 * A post cover's Article image set, absolute: the 16:9, 4:3 and 1:1 crops at 1200 wide Google asks for, versioned. Empty
 * for a cover that is not a /media raster whose key spells its size, so the JSON-LD keeps its one share image.
 *
 * @param {string | null} src the cover's path
 * @param {string} origin
 */
export function articleCrops(src, origin) {
  const dimensions = src?.startsWith("/media/") ? dimensionsFromKey(src) : null;
  if (!src || !dimensions) return [];
  return images
    .articleImages({ src, ...dimensions, version: mediaContentVersion(src) })
    .map(({ url, width, height }) => ({ url: new URL(url, origin).href, width, height }));
}

/**
 * A picture in the prose column as a `<picture>`: a /media image at its stored size, else the size its key spells, gets
 * the content use with AVIF and WebP; anything else (a static file, an SVG) has no size to read and gets a plain `src`,
 * since an invented size would distort the image.
 *
 * @param {string} src
 * @param {{ alt: string, width?: number | null, height?: number | null, priority?: boolean, className?: string }} options
 */
export function contentPicture(src, { alt, width, height, priority = false, className }) {
  const dimensions = width && height ? { width, height } : dimensionsFromKey(src);
  const attrs =
    dimensions && src.startsWith("/media/")
      ? contentImage(src, dimensions)
      : {
          src,
          srcset: undefined,
          sizes: undefined,
          sources: [],
          width: dimensions?.width,
          height: dimensions?.height,
          background: undefined,
        };
  return pictureProps(attrs, { alt, priority, className });
}

app/lib/pages/compile.mjs.source:
// One door from a page file to everything derived from it: parse, validate, render, the markdown twin and
// the search input. build:content, sync:content and the adapter's page save all call compilePage, so
// a file CI passes is the file the save tool accepts and the page draws (docs/PAGES.md).

import { errorMessage } from "@dustinedwards/site-runtime/log";
import { matter } from "@drdustinedwards/site-helpers/matter";

import { gitBlobSha } from "../content/hashes.mjs";
import {
  CONTENT_PAGE_SECTIONS,
  DESCRIPTION_MAX,
  LEGAL_BANNER,
  LEGAL_PAGE_PATHS,
  PAGE_FILE_PATHS,
  SEO_TITLE_MAX,
  contentPageFile,
  contentPageMarkdownBody,
  contentPageSearchInputs,
  markdownTableFacts,
} from "../content-pages.mjs";
import { IDENTITY } from "../identity.generated.mjs";
import { expandPhagePage, expandPhageTokens, withPhageRowIds } from "../phages/compile.mjs";
import { pageInvariantErrors } from "./invariants.mjs";
import { protectedPageReason } from "./protected.mjs";
import { wideDashError } from "../content/front-matter.mjs";

export const PAGES_DIR = "content/pages";

/** The identity facts a page may state by token ({{identity.role}}): text, from the CV (app/lib/identity.mjs). */
export const IDENTITY_TOKEN_KEYS = /** @type {const} */ ([
  "name",
  "degree",
  "discipline",
  "disciplineLower",
  "rank",
  "role",
  "adminTitle",
  "jobTitle",
  "cvTitle",
  "department",
  "departmentSubject",
  "affiliation",
]);
const IDENTITY_TOKEN = /\{\{\s*identity\.([A-Za-z]+)\s*\}\}/g;

/**
 * Every token a page can carry, filled: the owner's identity from the CV, then the phage facts from the rows. A
 * title, a role or a headship a page states is read, never typed, so a CV change updates the page. A token that
 * names nothing is an error, never an empty string.
 *
 * @param {string} text
 * @param {import("../phages/compile.mjs").Phage[] | undefined} phages
 * @returns {{ ok: true, text: string } | { ok: false, errors: string[] }}
 */
export function expandPageTokens(text, phages) {
  /** @type {string[]} */
  const errors = [];
  const withIdentity = text.replace(IDENTITY_TOKEN, (whole, key) => {
    if (!(/** @type {readonly string[]} */ (IDENTITY_TOKEN_KEYS).includes(key))) {
      errors.push(`${whole} is not an identity fact (${IDENTITY_TOKEN_KEYS.join(", ")})`);
      return whole;
    }
    return String(/** @type {Record<string, unknown>} */ (IDENTITY)[key]);
  });
  if (errors.length > 0) return { ok: false, errors };
  return expandPhageTokens(withIdentity, phages);
}

/** The repository path of a page's file, from its file key (`research-phages`). */
export function pageSourcePath(/** @type {string} */ slug) {
  return `${PAGES_DIR}/${slug}.md`;
}

/** The file key of a registered path: `/research/phages` is `research-phages`. */
export function pageSlug(/** @type {string} */ path) {
  return contentPageFile(path).slice(0, -3);
}

/** The registered path a file key stands for, or undefined when no page file may have that key. */
export function pagePathForSlug(/** @type {string} */ slug) {
  return PAGE_FILE_PATHS.find((path) => pageSlug(path) === slug);
}

/** The schema.org types a page may declare; app/routes/content-page.tsx shapes a node for each. */
const SCHEMA_TYPES = ["SoftwareApplication", "SoftwareSourceCode", "WebSite", "WebPage", "Dataset"];

/**
 * @typedef {{
 *   schemaType?: string,
 *   productUrl?: string,
 *   codeRepository?: string,
 *   applicationCategory?: string,
 *   license?: string,
 *   programmingLanguage?: string,
 *   runtimePlatform?: string,
 *   spatialCoverage?: string,
 *   dataset?: { variableMeasured: string[], temporalCoverage: string | null, rows: number },
 * }} PageSchema
 *
 * What only a legal page states (LEGAL_PAGE_PATHS): `banner` is the one word "Draft", `lastUpdated` an ISO date.
 * @typedef {{ banner?: string, lastUpdated?: string }} PageLegal
 *
 * @typedef {{ depth: number, id: string, text: string }} TocEntry
 *
 * The page as the routes, the search index and the gates read it. `markdown` is the body without front
 * matter; the twin a machine reads is built from it (contentPageMarkdownBody).
 * @typedef {{
 *   path: string, title: string, seoTitle: string, description: string, html: string,
 *   markdown: string, toc: TocEntry[],
 * } & PageSchema & PageLegal} CompiledPage
 *
 * What D1's `record` column holds: the page less its markdown, with its file key and draft flag.
 * @typedef {Omit<CompiledPage, "markdown"> & { slug: string, draft: boolean }} PageRecord
 */

/**
 * The structured-data facts a page's front matter states, each only when it is written there: the JSON-LD
 * says what the page holds and never fills a gap. A Dataset also carries what its first table says.
 *
 * @param {Record<string, unknown>} fm
 * @param {string} markdown
 * @param {string[]} errors
 * @returns {PageSchema}
 */
function pageSchema(fm, markdown, errors) {
  const text = (/** @type {unknown} */ value) =>
    value == null || value === "" ? "" : String(value);
  const schemaType = text(fm.schema_type);
  if (schemaType && !SCHEMA_TYPES.includes(schemaType)) {
    errors.push(`schema_type "${schemaType}" is not one of ${SCHEMA_TYPES.join(", ")}`);
  }
  const codeRepository = text(fm.code_repository);
  if (codeRepository && !["SoftwareApplication", "SoftwareSourceCode"].includes(schemaType)) {
    errors.push(
      "code_repository is only stated for software (schema_type SoftwareApplication or SoftwareSourceCode)",
    );
  }
  const dataset = schemaType === "Dataset" ? markdownTableFacts(markdown) : null;
  if (schemaType === "Dataset" && !dataset) {
    errors.push("schema_type is Dataset but the page has no markdown table for it to describe");
  }
  /** @type {Array<[Exclude<keyof PageSchema, "dataset">, string]>} */
  const fields = [
    ["schemaType", schemaType],
    ["productUrl", text(fm.product_url)],
    ["codeRepository", codeRepository],
    ["applicationCategory", text(fm.application_category)],
    ["license", text(fm.license)],
    ["programmingLanguage", text(fm.programming_language)],
    ["runtimePlatform", text(fm.runtime_platform)],
    ["spatialCoverage", text(fm.spatial_coverage)],
  ];
  /** @type {PageSchema} */
  const schema = dataset ? { dataset } : {};
  for (const [key, value] of fields) if (value !== "") schema[key] = value;
  return schema;
}

/**
 * The banner and the last-updated date a legal page states, each only when it is written there. The banner is
 * the single word "Draft" and nothing else; the date is a real calendar day. Neither belongs on any other page.
 * YAML reads an unquoted `2026-10-06` as a Date and rolls an impossible `2026-02-30` over to March, so the
 * day is read from the front matter's own text, the way it was written, and the parsed value only when the
 * line cannot be found.
 *
 * @param {Record<string, unknown>} fm
 * @param {string} frontMatter the front matter's text, as written
 * @param {string} path
 * @param {string[]} errors
 * @returns {PageLegal}
 */
function pageLegal(fm, frontMatter, path, errors) {
  /** @type {PageLegal} */
  const legal = {};
  const banner = fm.banner == null ? "" : String(fm.banner).trim();
  if (banner !== "") {
    if (banner !== LEGAL_BANNER)
      errors.push(
        `banner is ${JSON.stringify(banner)}; the one word it may say is "${LEGAL_BANNER}"`,
      );
    else legal.banner = banner;
  }
  const written = /^last_updated:[ \t]*["']?([^"'#\r\n]*?)["']?[ \t]*(?:#.*)?$/m.exec(
    frontMatter,
  )?.[1];
  const raw = written ?? fm.last_updated;
  if (raw != null && raw !== "") {
    const day = raw instanceof Date ? raw.toISOString().slice(0, 10) : String(raw).trim();
    const real =
      /^\d{4}-\d{2}-\d{2}$/.test(day) &&
      new Date(`${day}T00:00:00.000Z`).toISOString().slice(0, 10) === day;
    if (real) legal.lastUpdated = day;
    else errors.push(`last_updated is ${JSON.stringify(day)}; it is a real day written YYYY-MM-DD`);
  }
  if (
    (legal.banner || legal.lastUpdated || fm.banner != null || fm.last_updated != null) &&
    !LEGAL_PAGE_PATHS.includes(path)
  ) {
    errors.push(
      `banner and last_updated belong to the legal pages (${LEGAL_PAGE_PATHS.join(", ")}), not to ${path}`,
    );
  }
  return legal;
}

/**
 * The page's dictionary entry (docs/DICTIONARY.md), when it has a published one, leads its twin and its search
 * record, so `entry` is the caller's to give: the build reads it from content/dictionary, the Worker from D1.
 *
 * @param {{
 *   slug: string,
 *   raw: string,
 *   pipeline: { renderBody: (input: { file: string, body: string, resolveImage: (src: string) => Promise<never> }) => Promise<{ html: string, toc: TocEntry[], blockedUrls: Array<{ url: string }> }>,
 *               findWideDashes: (text: string) => Array<{ line: number, column: number, char: string, excerpt: string }> },
 *   sourcePath?: string,
 *   generated?: boolean,
 *   entry?: import("../dictionary-entries.mjs").DictionaryEntry,
 *   phages?: import("../phages/compile.mjs").Phage[],
 * }} input
 * @returns {Promise<
 *   | { ok: false, errors: string[] }
 *   | { ok: true, errors: [], page: CompiledPage, record: PageRecord, draft: boolean, markdown: string,
 *       searchInput: ReturnType<typeof contentPageSearchInputs>[number], sourcePath: string, sourceBlobSha: string }
 * >}
 */
export async function compilePage({
  slug,
  raw,
  pipeline,
  sourcePath,
  generated = false,
  entry,
  phages,
}) {
  const expectedPath = pagePathForSlug(slug);
  if (!expectedPath) {
    return {
      ok: false,
      errors: [
        `"${slug}" is not a registered page. A page's address is structure: add the path to CONTENT_PAGE_PATHS ` +
          "(app/lib/content-pages.mjs) in code, and a save can then write its file; a save cannot create a new path",
      ],
    };
  }
  const file = sourcePath ?? pageSourcePath(slug);
  /** @type {string[]} */
  const errors = (generated ? [] : pipeline.findWideDashes(raw)).map(wideDashError);

  let parsed;
  try {
    parsed = matter(raw);
  } catch (error) {
    return {
      ok: false,
      errors: [...errors, `the front matter is not valid YAML: ${errorMessage(error)}`],
    };
  }
  const fm = /** @type {Record<string, unknown>} */ (parsed.data);
  // A phage fact a page states (the count, the span, a genome's size) is read from the phage rows by a token,
  // never typed, so the title and description fill the same way the body does.
  /** @param {unknown} value @returns {string} */
  const filled = (value) => {
    const result = expandPageTokens(String(value ?? ""), phages);
    if (!result.ok) {
      errors.push(...result.errors);
      return String(value ?? "");
    }
    return result.text;
  };
  const page = {
    path: String(fm.path ?? ""),
    title: filled(fm.title),
    seoTitle: filled(fm.seo_title),
    description: filled(fm.description),
  };
  if (page.path !== expectedPath) {
    errors.push(
      `path is "${page.path}", but ${contentPageFile(expectedPath)} is the file for ${expectedPath}: every page ` +
        "must be listed in CONTENT_PAGE_PATHS (app/lib/content-pages.mjs) and its file must say so",
    );
  }
  for (const [field, value] of [
    ["title", page.title],
    ["seo_title", page.seoTitle],
    ["description", page.description],
  ]) {
    if (!value) errors.push(`${field} is required`);
  }
  if (page.seoTitle.length > SEO_TITLE_MAX) {
    errors.push(
      `seo_title is ${page.seoTitle.length} characters (at most ${SEO_TITLE_MAX}); Google would clip it`,
    );
  }
  if (page.description.length > DESCRIPTION_MAX) {
    errors.push(
      `description is ${page.description.length} characters (at most ${DESCRIPTION_MAX}); Google would clip it`,
    );
  }
  if (fm.draft !== undefined && typeof fm.draft !== "boolean") {
    errors.push(`draft is ${JSON.stringify(fm.draft)}; it is true or false`);
  }
  // The phage page's table is drawn from the phage rows where the file's marker says (docs/PHAGES.md), before
  // anything reads the body, so its HTML, twin, dataset facts and search record all come from one text. Every
  // other page passes through unchanged.
  const drawn = expandPhagePage(page.path, parsed.content, phages);
  if (!drawn.ok) errors.push(...drawn.errors);
  const drawnBody = drawn.ok
    ? expandPageTokens(drawn.markdown, phages)
    : /** @type {const} */ ({ ok: true, text: parsed.content });
  if (!drawnBody.ok) errors.push(...drawnBody.errors);
  const body = drawnBody.ok ? drawnBody.text : parsed.content;
  const schema = pageSchema(fm, body, errors);
  const legal = pageLegal(fm, parsed.matter, page.path, errors);
  const keep = protectedPageReason(page.path);
  if (keep && fm.draft === true) errors.push(`draft is true, but ${keep}`);
  if (errors.length > 0) return { ok: false, errors };

  let rendered;
  try {
    rendered = await pipeline.renderBody({
      file,
      body,
      resolveImage: async (src) => {
        throw new Error(
          `the page references an image ("${src}") and these pages have no image pipeline`,
        );
      },
    });
  } catch (error) {
    return { ok: false, errors: [errorMessage(error)] };
  }
  if (rendered.blockedUrls.length > 0) {
    errors.push(
      `links the URL allowlist refused: ${rendered.blockedUrls.map((b) => b.url).join(", ")}`,
    );
  }
  for (const section of CONTENT_PAGE_SECTIONS) {
    const [sectionPath, id] = section.split("#");
    if (sectionPath === page.path && !rendered.toc.some((heading) => heading.id === id)) {
      errors.push(
        `no heading has the id "${id}", which CONTENT_PAGE_SECTIONS (app/lib/content-pages.mjs) lists for the header menu`,
      );
    }
  }

  /** @type {CompiledPage} */
  const compiled = {
    ...page,
    html: withPhageRowIds(page.path, rendered.html, phages),
    markdown: body,
    toc: rendered.toc,
    ...schema,
    ...legal,
  };
  errors.push(...pageInvariantErrors(compiled, { phages }));
  if (errors.length > 0) return { ok: false, errors };

  const draft = fm.draft === true;
  const { markdown: _body, ...rest } = compiled;
  const [searchInput] = contentPageSearchInputs([compiled], () => entry);
  if (!searchInput) throw new Error(`no search input was made for ${page.path}`);
  return {
    ok: true,
    errors: [],
    page: compiled,
    record: { slug, draft, ...rest },
    draft,
    markdown: contentPageMarkdownBody(compiled, entry),
    searchInput,
    sourcePath: file,
    sourceBlobSha: await gitBlobSha(raw),
  };
}

