import { ICONS } from "@drdustinedwards/site-helpers/icons";
import { toHex } from "@dustinedwards/site-runtime/encoding";

const TYPES = new Map([
  ["png", { kind: "image", mime: "image/png" }],
  ["jpg", { kind: "image", mime: "image/jpeg" }],
  ["jpeg", { kind: "image", mime: "image/jpeg" }],
  ["webp", { kind: "image", mime: "image/webp" }],
  ["avif", { kind: "image", mime: "image/avif" }],
  ["gif", { kind: "image", mime: "image/gif" }],
  ["svg", { kind: "image", mime: "image/svg+xml" }],
  ["ico", { kind: "image", mime: "image/x-icon" }],
  ["pdf", { kind: "document", mime: "application/pdf" }],
  // A chart's data from the media library (upload-contract.mjs DATA_TYPES).
  ["csv", { kind: "document", mime: "text/csv; charset=utf-8" }],
  ["webmanifest", { kind: "other", mime: "application/manifest+json" }],
  // The pronunciation clips under /audio/ (content/dictionary/*.md), generated once, never per visit.
  ["mp3", { kind: "other", mime: "audio/mpeg" }],
  // The SIL OFL requires the font license to be served with the fonts.
  ["txt", { kind: "document", mime: "text/plain; charset=utf-8" }],
  // No woff2: fonts live in app/fonts/, so a webfont dropped into public/ should stop the build.
]);

const RASTER = new Set(["png", "jpg", "jpeg", "webp", "avif", "gif"]);

/**
 * The "" for no extension is load-bearing: `classify()` throws on it, which stops the build.
 * Not the display label; that is `extensionLabel` in media-document-card.tsx.
 *
 * @param {string} pathOrKey
 */
function extensionOf(pathOrKey) {
  const base = pathOrKey.split("/").pop() ?? "";
  const dot = base.lastIndexOf(".");
  return dot === -1 ? "" : base.slice(dot + 1).toLowerCase();
}

/**
 * THROWS on an unknown extension: a new file type under `public/` must stop the build, not get a
 * plausible `kind` nobody chose.
 *
 * @param {string} pathOrKey
 * @returns {{ kind: string, mime: string, extension: string }}
 */
export function classify(pathOrKey) {
  const extension = extensionOf(pathOrKey);
  const type = TYPES.get(extension);
  if (!type) {
    throw new Error(
      `unclassified asset "${pathOrKey}": extension "${extension || "(none)"}" is not in ` +
        `app/lib/media/classify.mjs. Add it there, in the same commit as the file.`,
    );
  }
  return { kind: type.kind, mime: type.mime, extension };
}

// Deploy-time control files: Cloudflare consumes them and never serves them. Named, not a rule, because
// "skip anything extensionless" would fail open. Do NOT add /fonts/dustin-edwards-ofl.txt: it is served,
// so it is an asset; if index drift reports it, the repair is the rebuild on /admin/media.
const NOT_ASSETS = new Map([
  [
    "/_headers",
    "Cloudflare static-asset header rules. Consumed by the uploader at deploy " +
      "time and never served, so it has no URL to index. Written by site-runtime-headers.",
  ],
  ["/_redirects", "Cloudflare static-asset redirect rules. Same deploy-time contract as _headers."],
  [
    "/sw.js",
    "The offline service worker (app/enhance/offline.ts). Code the browser registers, not media.",
  ],
  [
    "/diagrams/sizes.json",
    "Widths and heights for a mermaid drawing that is still an image. The content build reads the file; the page does not request it, so it is not a picture in the library.",
  ],
]);

// A pattern is allowed here because it matches only the slug shape paths.mjs generates. The twins are
// gitignored build product, not media; llms.txt lists them and check:content reconciles it.
const NOT_ASSET_PATTERNS = [
  {
    test: /^\/research\/publications\/[a-z0-9-]+\.md$/,
    why:
      "A generated markdown twin of a paper, gitignored build product served " +
      "as an asset. Listed in llms.txt and reconciled by check:content; " +
      "not media, and not committed, so not in this manifest.",
  },
];

/**
 * @param {string} pathOrKey
 * @returns {string | null}
 */
export function excludedFromAssets(pathOrKey) {
  const named = NOT_ASSETS.get(pathOrKey);
  if (named) return named;
  return NOT_ASSET_PATTERNS.find((rule) => rule.test.test(pathOrKey))?.why ?? null;
}

/**
 * @param {string} pathOrKey
 */
export function isRaster(pathOrKey) {
  return RASTER.has(extensionOf(pathOrKey));
}

/**
 * Static assets are indexed under their public path, which starts with `/`; an R2 key never does.
 *
 * @param {string} pathOrKey
 * @returns {"static" | "r2-derived" | "r2"}
 */
export function storageOf(pathOrKey) {
  if (pathOrKey.startsWith("/")) return "static";
  // `derived/` holds objects the Worker renders from its own data (the CV PDF, app/lib/cv/pdf.server.ts). It is its
  // own prefix, not `og/`, because build:og prunes every `og/` key no post references.
  if (pathOrKey.startsWith("og/") || pathOrKey.startsWith("derived/")) return "r2-derived";
  return "r2";
}

/**
 * Typed generically rather than against `Env`: this module is shared with the Node build scripts.
 * A `static` key resolves to MEDIA, where the miss is loud in the index drift check.
 *
 * @template T
 * @param {{ OG: T, MEDIA: T }} env
 * @param {string} key
 * @returns {T}
 */
export function bucketFor(env, key) {
  return storageOf(key) === "r2-derived" ? env.OG : env.MEDIA;
}

/**
 * Diagrams are light/dark pairs, so inserting one alone bypasses `:::diagram`; hence `generated`.
 * `icon` is fetched by the platform (a `<link rel>` or the webmanifest); `brand` is named by
 * application code. The default is `content`: an unknown asset should be visible in the picker.
 *
 * @param {string} pathOrKey
 * @returns {"content" | "brand" | "generated" | "icon"}
 */
export function roleOf(pathOrKey) {
  if (pathOrKey.startsWith("og/") || pathOrKey.startsWith("derived/")) return "generated";
  if (pathOrKey.startsWith("/diagrams/")) return "generated";

  // The OG image is brand, not icon: `seo.ts` names it as the default social card.
  if (/^\/dustin-edwards-(logo(-[a-z]+)*\.svg|og-image\.png)$/.test(pathOrKey)) {
    return "brand";
  }

  // Prelum's shared icon paths, which browsers request unprompted.
  if (/** @type {string[]} */ (Object.values(ICONS)).includes(pathOrKey)) return "icon";

  return "content";
}

/**
 * 16 hex characters (64 bits) is ample at this corpus size. The key carries `-<w>x<h>` so the Node build
 * and the Worker produce the same stored HTML without either reading bytes; the digest pins the bytes,
 * so it cannot go stale. The same image under two names is two objects.
 *
 * @param {ArrayBuffer | Uint8Array} digest
 * @param {string} extension
 * @param {{ width: number, height: number } | null} [dimensions]
 * @param {string | null} [name]
 */
export function contentKey(digest, extension, dimensions = null, name = null) {
  const hex = toHex(digest);
  const size =
    dimensions && dimensions.width > 0 && dimensions.height > 0
      ? `-${dimensions.width}x${dimensions.height}`
      : "";
  const slug = slugifyName(name);
  return `${ASSET_PREFIX}${slug ? `${slug}-` : ""}${hex.slice(0, 16)}${size}.${extension}`;
}

export const ASSET_PREFIX = "dustin-edwards-";

/**
 * Capped at 48 so whoever names the upload cannot decide key length. A name already carrying the
 * prefix loses it, or re-uploading a downloaded file would double it.
 *
 * @param {string | null | undefined} name
 * @returns {string}
 */
function slugifyName(name) {
  if (typeof name !== "string") return "";
  return name
    .replace(/\.[^.]*$/, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+/, "")
    .replace(/^(?:dustin-edwards(?:-|$))+/, "")
    .slice(0, 48)
    .replace(/-+$/, "");
}

// The only statement of the key grammar. No character class admits a slash, so static paths, `og/` keys
// and traversal all fail. Named groups, not indices. The slug is GREEDY so the LAST 16-hex run is the
// digest. `[1-9]` refuses a leading-zero dimension; the parameter type keeps `contentKey` from writing one.
const CONTENT_KEY_SHAPE =
  /^dustin-edwards-(?:(?<slug>[a-z0-9][a-z0-9-]*)-)?(?<digest>[0-9a-f]{16})(?:-(?<width>[1-9]\d{0,4})x(?<height>[1-9]\d{0,4}))?\.[a-z0-9]+$/;

/**
 * `?w=320` is a transform request, not a different object, so query and fragment come off.
 *
 * @param {string} keyOrPath
 * @returns {string | null}
 */
function bareKey(keyOrPath) {
  if (typeof keyOrPath !== "string") return null;
  const path = keyOrPath.split(/[?#]/)[0] ?? "";
  return path.startsWith("/media/") ? path.slice("/media/".length) : path;
}

/**
 * Strict: a malformed, zero or oversized segment returns null, which fails the build at the call site
 * rather than silently dropping the dimensions that prevent layout shift.
 *
 * @param {string} keyOrPath
 * @returns {{ width: number, height: number } | null}
 */
export function dimensionsFromKey(keyOrPath) {
  const key = bareKey(keyOrPath);
  if (key === null) return null;
  const match = CONTENT_KEY_SHAPE.exec(key);
  if (!match || match.groups?.width === undefined) return null;
  return { width: Number(match.groups.width), height: Number(match.groups.height) };
}

/**
 * Nothing outside this module may parse a content key (test/media-key-grammar.test.mjs).
 *
 * @param {string} key a bare key, never a `/media/` path
 * @returns {boolean}
 */
export function isContentKey(key) {
  return typeof key === "string" && CONTENT_KEY_SHAPE.test(key);
}

/**
 * @param {string} keyOrPath
 * @returns {string | null}
 */
export function digestFromKey(keyOrPath) {
  const key = bareKey(keyOrPath);
  if (key === null) return null;
  const match = CONTENT_KEY_SHAPE.exec(key);
  return match?.groups?.digest ?? null;
}

app/lib/operator/sync-report.mjs.source:
// `converged` is DERIVED from counts read back after the writes, never asserted by the caller: `ship`
// fails on it, and a run's own counters would report a healthy number over a wrong index.

/**
 * The Ask index after a sync has ended: one item per row of its query, so the counts are the read-back. A sync that
 * had not ended inside the wait, or a row the index refused, makes `converged` false even when the counts agree.
 *
 * @param {{
 *   job: string,
 *   ended: boolean,
 *   expected: number,
 *   present: number,
 *   refused: number,
 *   indexing: number,
 * }} counts
 * @returns {{
 *   job: string,
 *   ended: boolean,
 *   expected: number,
 *   present: number,
 *   drift: number,
 *   refused: number,
 *   indexing: number,
 *   converged: boolean,
 * }}
 */
export function askSyncReport(counts) {
  const agreement = convergence(counts.expected, counts.present);
  const refused = whole(counts.refused);
  return {
    job: String(counts.job),
    ended: counts.ended === true,
    ...agreement,
    refused,
    indexing: whole(counts.indexing),
    converged:
      agreement.converged &&
      counts.ended === true &&
      Number.isInteger(counts.refused) &&
      refused === 0,
  };
}

/**
 * ABSOLUTE drift: an index holding more than its source is stale too, and a negative number would read
 * as healthy to a caller testing `drift > 0`.
 *
 *
 * @param {unknown} expectedRaw @param {unknown} presentRaw
 * @returns {{ expected: number, present: number, drift: number, converged: boolean }}
 */
function convergence(expectedRaw, presentRaw) {
  const expected = whole(expectedRaw);
  const present = whole(presentRaw);
  const drift = Math.abs(expected - present);
  return {
    expected,
    present,
    drift,
    converged: unreadable(expectedRaw, presentRaw) ? false : drift === 0,
  };
}

/**
 * Media drifts by KEY: dropping one file while inventing one row leaves the totals equal, so drift is
 * `missing` plus `extra`, not a count difference.
 *
 *
 * @param {{
 *   indexed: number,
 *   removed: number,
 *   failures: string[],
 *   expected: number,
 *   present: number,
 *   missing: string[],
 *   extra: string[],
 * }} counts
 */
export function mediaSyncReport(counts) {
  const totals = convergence(counts.expected, counts.present);
  const missing = list(counts.missing);
  const extra = list(counts.extra);
  const drift = missing.length + extra.length;
  const failures = list(counts.failures);
  // Fails closed: a list that is not an array of strings cannot say what is missing or what failed, so
  // the report does not converge on it.
  const readable = [counts.missing, counts.extra, counts.failures].every(stringList);

  return {
    indexed: whole(counts.indexed),
    removed: whole(counts.removed),
    expected: totals.expected,
    present: totals.present,
    drift,
    missing,
    extra,
    failures,
    // A failed derivation leaves no row and no source change, so the key sets can agree while wrong.
    converged: totals.converged && readable && drift === 0 && failures.length === 0,
    unreadable: !readable,
  };
}

/** @param {unknown} v @returns {string[]} */
function list(v) {
  return Array.isArray(v) ? v.filter((x) => typeof x === "string") : [];
}

/** @param {unknown} v @returns {boolean} */
function stringList(v) {
  return Array.isArray(v) && v.every((x) => typeof x === "string");
}

/**
 * An unreadable count is not a passing count.
 *
 * @param {unknown} a @param {unknown} b
 */
function unreadable(a, b) {
  return !Number.isInteger(a) || !Number.isInteger(b);
}

/** @param {unknown} n @returns {number} */
function whole(n) {
  return Number.isInteger(n) ? Number(n) : 0;
}

app/lib/pages/links.mjs.source:
// The internal links of a page, judged at save time. check:links is CI's full gate over every link the
// site publishes, built from the repository's sources; a save through the operator API is live before CI
// runs, so the part of that judgment a Worker can make from D1 and code is made here, with the same
// gateway functions the router uses (docs/PAGES.md).
//
// It refuses only what it can PROVE broken: a link into a namespace this module can list completely
// (the Research, Teaching, Software and recipe pages, the procedures, the posts) that names nothing in
// it, a path the gateway answers 410, a draft post, and an anchor missing from a content page. Any other
// address passes here and is left to check:links.

import { CONTENT_PAGE_PATHS, contentPageMarkdownPath } from "../content-pages.mjs";
import { safeDecode } from "../safe-decode.mjs";
import { wordpressDisposition } from "../wordpress-redirects.mjs";
import { unescapeHtml } from "@dustinedwards/site-runtime/html";

/**
 * @typedef {{
 *   procedurePaths: ReadonlySet<string>,
 *   posts: ReadonlyMap<string, boolean>,
 *   idsOf: (path: string) => ReadonlySet<string> | null,
 * }} AddressBook
 * `posts` maps `/writing/<slug>` to whether a reader can open it; `idsOf` is the element ids a content
 * page carries, or null for a path that is not one.
 */

const SITE_HOST = /^https?:\/\/(?:www\.)?dustinedwards\.info(?=[/?#]|$)/i;

/** Every element id in rendered HTML. */
export function idsIn(/** @type {string} */ html) {
  return new Set([...html.matchAll(/\sid="([^"]+)"/g)].map((m) => unescapeHtml(m[1] ?? "")));
}

const PAGE_SET = new Set(/** @type {readonly string[]} */ (CONTENT_PAGE_PATHS));
const PAGE_TWINS = new Set(CONTENT_PAGE_PATHS.map((p) => contentPageMarkdownPath(p)));

/** The namespaces this module can list completely. */
const OWNED = /^\/(?:research|teaching|software|recipes|writing)(?:\/|$)/;
/** Listed elsewhere: papers and citation exports, the lab registry (strains, primers), feeds, tag and series pages. */
const NOT_LISTED =
  /^\/(?:research\/publications|research\/lab|writing\/(?:tags|series|rss\.xml|feed\.json|atom\.xml))(?:[/.]|$)/;

/**
 * @param {string} path
 * @param {AddressBook} book
 * @param {number} [hops]
 * @returns {{ kind: "ok" | "unlisted" | "gone" | "draft" | "missing", path: string }}
 */
function resolve(path, book, hops = 0) {
  if (hops > 5) return { kind: "missing", path };
  const redirect = wordpressDisposition(path);
  if (redirect?.status === 410) return { kind: "gone", path };
  if (redirect?.status === 301)
    return resolve(redirect.location.split("#")[0] ?? "", book, hops + 1);
  if (!OWNED.test(path) || NOT_LISTED.test(path)) return { kind: "unlisted", path };
  if (PAGE_SET.has(path) || PAGE_TWINS.has(path)) return { kind: "ok", path };
  const procedure = path.replace(/(?:\.md|\/sheet)$/, "");
  if (book.procedurePaths.has(procedure)) return { kind: "ok", path };
  const visible = book.posts.get(path.replace(/\.md$/, ""));
  if (visible !== undefined) return { kind: visible ? "ok" : "draft", path };
  return { kind: "missing", path };
}

/**
 * @param {{ html: string }} page
 * @param {AddressBook} book
 * @returns {string[]}
 */
export function pageLinkErrors({ html }, book) {
  /** @type {string[]} */
  const errors = [];
  const seen = new Set();
  for (const raw of [...html.matchAll(/\shref="([^"]*)"/g)].map((m) => unescapeHtml(m[1] ?? ""))) {
    const href = SITE_HOST.test(raw) ? raw.replace(SITE_HOST, "") || "/" : raw;
    if (!href.startsWith("/") || href.startsWith("//") || seen.has(href)) continue;
    seen.add(href);
    const [pathAndQuery = "", anchor] = href.split("#");
    const path = (pathAndQuery.split("?")[0] ?? "").replace(/(.)\/+$/, "$1");
    const found = resolve(path, book);
    if (found.kind === "gone")
      errors.push(`the link ${href} goes to ${path}, which the site answers 410 Gone`);
    else if (found.kind === "draft")
      errors.push(
        `the link ${href} goes to a draft or scheduled post, which every reader gets a 404 for`,
      );
    else if (found.kind === "missing")
      errors.push(`the link ${href} goes to ${found.path}, which this site does not serve`);
    else if (found.kind === "ok" && anchor && found.path === path) {
      const ids = book.idsOf(found.path);
      if (ids && !ids.has(safeDecode(anchor)))
        errors.push(`the link ${href} names an anchor that ${found.path} does not have`);
    }
  }
  return errors;
}

app/lib/publications/compile.mjs.source:
// One door from a publication file to everything derived from it: parse, validate, the record every
// surface reads, the markdown twin and the search input. check:content, sync:content, the
// build and the Carrel adapter's save all call compilePublication, so a file CI passes is the file the
// save accepts and the page draws, and the twin a machine reads is the one a person's page agrees with.

import { errorMessage } from "@dustinedwards/site-runtime/log";
import { gitBlobSha } from "../content/hashes.mjs";
import { urlForRowId } from "../search/ask-citations.mjs";
import { citationTags, REQUIRED_CITATION_TAGS } from "@drdustinedwards/site-helpers/scholar";
import { citedByFetchedAt, citedByFor } from "./cited-by.mjs";
import { unescapeHtml } from "@dustinedwards/site-runtime/html";
import { organismsIn, paperBibtex, paperRis } from "./exports.mjs";
import { parsePublication, publicationPath } from "./parse.mjs";
import { paperAskUrl, paperPath, paperPdfPath } from "./paths.mjs";
import { recordFromData } from "./record.mjs";
import { paperSearchInputs } from "./search-inputs.mjs";
import { paperTwin } from "./twin.mjs";
import { ASK_URL_MAX, validatePublicationFile } from "./validate.mjs";

const ORIGIN = "https://example.invalid";
const REFERENCE = /&(?:amp|lt|gt|quot|apos|#\d+);/;

/**
 * What a record promises other surfaces, checked once it is built: the Scholar tag set, the exports,
 * the twin, the search record and the Ask key. Each is a function of the record alone, so a file that
 * passes here cannot fail the page at render time.
 *
 * @param {import("./types.ts").Publication} record
 * @param {{ twin: string, searchBody: string, fullText: string | null }} built
 * @returns {string[]}
 */
function derivedProblems(record, built) {
  /** @type {string[]} */
  const errors = [];
  const { slug } = record;
  const hosted = record.access === "self-hosted" && record.pdfPath !== null;

  if (record.doi !== null) {
    try {
      const tags = citationTags(record, {
        abstractUrl: `${ORIGIN}${paperPath(slug)}`,
        pdfUrl: hosted ? `${ORIGIN}${paperPdfPath(slug)}` : null,
      });
      const names = tags.map((t) => t.name);
      for (const required of REQUIRED_CITATION_TAGS) {
        if (!names.includes(required)) errors.push(`citation tags: no ${required}`);
      }
      const authorTags = tags.filter((t) => t.name === "citation_author").length;
      if (authorTags !== record.authors.length) {
        errors.push(
          `citation tags: ${authorTags} citation_author tags for ${record.authors.length} authors; one per author, or Scholar reads a single author whose name is the whole list`,
        );
      }
      const pdf = tags.find((t) => t.name === "citation_pdf_url");
      if (hosted && !pdf) errors.push("citation tags: hosted but no citation_pdf_url");
      if (!hosted && pdf) errors.push("citation tags: not hosted but has citation_pdf_url");
      if (pdf && !pdf.content.startsWith(`${ORIGIN}${paperPath(slug)}`)) {
        errors.push(`citation tags: citation_pdf_url is not under ${paperPath(slug)}`);
      }
    } catch (error) {
      errors.push(errorMessage(error));
    }

    const bib = paperBibtex(record);
    const ris = paperRis(record);
    if (!bib.includes(record.doi) || !ris.includes(record.doi))
      errors.push("exports: the DOI is missing from the BibTeX or RIS entry");
    if (record.doi !== record.doi.toLowerCase() && !bib.includes(`doi = {${record.doi}}`)) {
      errors.push("exports: a mixed-case DOI must be exported as deposited");
    }
    if (REFERENCE.test(bib) || REFERENCE.test(ris))
      errors.push("exports: a character reference survives into BibTeX or RIS");
    const unprotected = organismsIn(record.title).filter((o) => !bib.includes(`{${o}}`));
    if (unprotected.length > 0)
      errors.push(
        `exports: organism name(s) not brace-protected in BibTeX: ${unprotected.join(", ")}`,
      );
  }

  if (REFERENCE.test(built.twin)) errors.push("twin: carries an undecoded character reference");
  if (hosted && built.fullText !== null && !built.twin.includes("## Full text"))
    errors.push("twin: a hosted paper's twin lacks its Full text section");
  // Classic search shows the line it matched, so two-column text would snippet a mangled one.
  if (hosted && built.fullText && built.searchBody.length > built.fullText.length / 2) {
    errors.push(
      "search record: the body carries the PDF text; only the abstract, summary and citation belong in it",
    );
  }

  // The Ask index's id for a paper is its page (ASK_INDEX_QUERY), and a citation is that id read back.
  if (urlForRowId(paperPath(slug)) !== paperPath(slug))
    errors.push(`Ask citation: ${paperPath(slug)} does not cite its own page`);
  const askUrl = paperAskUrl(unescapeHtml(record.title));
  if (!askUrl.startsWith("/search?q=") || askUrl.length > ASK_URL_MAX)
    errors.push("Ask link: the quoted title does not build a /search URL");
  return errors;
}

/**
 * @param {object} input
 * @param {string} input.slug
 * @param {string} input.raw the whole file
 * @param {import("./validate.mjs").PublicationHost} input.host
 * @param {import("./validate.mjs").OtherPublication[]} [input.others]
 * @param {unknown} input.citedByArtifact the parsed data/publications.cited-by.json, which the twin's
 *   citedBy line is a pure function of, so a build and a save write the same twin
 * @returns {Promise<
 *   | { ok: false, errors: string[] }
 *   | { ok: true, errors: [], record: import("./types.ts").Publication, draft: boolean, csl: Record<string, unknown> | null,
 *       fullText: string | null, pdfSha256: string | null, twin: string, searchInput: { uid: string, url: string, title: string, body: string },
 *       sourcePath: string, sourceBlobSha: string }
 * >}
 */
export async function compilePublication({ slug, raw, host, others, citedByArtifact }) {
  const file = publicationPath(slug);
  const parsed = parsePublication({ file, raw });
  const errors = await validatePublicationFile({ parsed, slug, host, others });
  if (errors.length > 0) return { ok: false, errors };

  const record = recordFromData(/** @type {any} */ (parsed.data), slug);
  const hosted = record.access === "self-hosted" && record.pdfPath !== null;
  const twin = paperTwin(record, {
    pages: hosted ? [parsed.fullText ?? ""] : null,
    citedBy: record.doi ? citedByFor(citedByArtifact, record.doi) : null,
    citedByFetchedAt: citedByFetchedAt(citedByArtifact),
    pagePath: paperPath(slug),
    pdfPath: hosted ? paperPdfPath(slug) : null,
  });
  const searchInput = /** @type {NonNullable<ReturnType<typeof paperSearchInputs>[number]>} */ (
    paperSearchInputs([record])[0]
  );
  const derived = derivedProblems(record, {
    twin,
    searchBody: searchInput.body,
    fullText: parsed.fullText,
  });
  if (derived.length > 0) return { ok: false, errors: derived };

  const csl =
    parsed.data.csl && typeof parsed.data.csl === "object"
      ? /** @type {Record<string, unknown>} */ (parsed.data.csl)
      : null;
  return {
    ok: true,
    errors: [],
    record,
    draft: parsed.data.draft === true,
    csl,
    fullText: parsed.fullText,
    pdfSha256: typeof parsed.data.pdfSha256 === "string" ? parsed.data.pdfSha256 : null,
    twin,
    searchInput,
    sourcePath: file,
    sourceBlobSha: await gitBlobSha(raw),
  };
}

app/lib/return-to.mjs.source:
/**
 * The `Referer` is attacker-supplied, so it is proven same-origin before the toggle redirects to it.
 *
 * @param {Request} request
 * @returns {string}
 */
export function safeReturnTo(request) {
  const referer = request.headers.get("referer");
  if (!referer) return "/";
  try {
    const url = new URL(referer);
    if (url.origin !== new URL(request.url).origin) return "/";
    // `new URL("https://site//evil.com")` has pathname `//evil.com`, and `Location: //evil.com`
    // is protocol-relative, resolving against another HOST. The origin check does not catch it.
    if (url.pathname.startsWith("//")) return "/";
    // `Referer` never carries a fragment (RFC 9110), so `url.hash` is empty for browser requests;
    // it is echoed for callers that pass a URL from elsewhere.
    return url.pathname + url.search + url.hash;
  } catch {
    return "/";
  }
}

app/lib/search/ask-citations.mjs.source:
// AI Search puts the id of the D1 row an indexed chunk came from on every chunk of it, as `row_id`
// (https://developers.cloudflare.com/ai-search/configuration/data-source/d1/#column-conventions), and the Ask
// index's ids are the pages' own URLs (ASK_INDEX_QUERY in search.server.ts), so a citation is its row id.

import { PUBLICATIONS_PATH } from "../publications/paths.mjs";

/**
 * A paper longer than one row may hold is indexed in parts, `<page>#part-2` and on. Every part cites the page.
 */
export const PAPER_PART = "#part-";

const POST_ID = /^\/writing\/[a-z0-9][a-z0-9-]*(#[^#\s]+)?$/;
const PAPER_ID = new RegExp(`^${PUBLICATIONS_PATH}/[a-z0-9][a-z0-9-]*/(${PAPER_PART}\\d+)?$`);

/**
 * The row id a chunk carries, or "" for a chunk that carries none.
 *
 * @param {unknown} chunk a chunk from AI Search's search, or from the `chunks` event of its chat completions
 * @returns {string}
 */
export function rowIdOf(chunk) {
  const id = /** @type {{ item?: { metadata?: { row_id?: unknown } } } | null} */ (chunk)?.item
    ?.metadata?.row_id;
  return typeof id === "string" ? id : "";
}

/**
 * The page a row id cites: a post or one of its sections as it is, a paper's part as the paper's page, with the
 * canonical trailing slash. Null for an id this site's query cannot produce, so nothing is guessed.
 *
 * @param {string} id
 * @returns {string | null}
 */
export function urlForRowId(id) {
  if (typeof id !== "string") return null;
  if (POST_ID.test(id)) return id;
  if (PAPER_ID.test(id)) return id.split(PAPER_PART)[0] ?? null;
  return null;
}

/**
 * The post a row id belongs to. Posts only: a paper has no posts row, and passing its URL as a slug would make every
 * answer citing it unreplayable forever.
 *
 * @param {string} id
 * @returns {string | null}
 */
export function slugForRowId(id) {
  if (typeof id !== "string" || !POST_ID.test(id)) return null;
  return (id.split("#")[0] ?? "").replace(/^\/writing\//, "") || null;
}

/**
 * @param {string} url
 * @returns {string}
 */
export function labelForUrl(url) {
  const [path, anchor] = url.split("#");
  // The slug, not a DOI: the DOI-to-slug fold is lossy, and a plausible reconstruction is worse than none.
  if ((path ?? "").startsWith(`${PUBLICATIONS_PATH}/`)) {
    return `Paper ${(path ?? "").replace(`${PUBLICATIONS_PATH}/`, "").replace(/\/$/, "")}`;
  }
  const target = anchor ?? (path ?? "").replace(/^\/writing\//, "");
  const words = target.replace(/^\d+-/, "").split("-").filter(Boolean);
  if (words.length === 0) return "Untitled";
  return words.join(" ").replace(/^./, (c) => c.toUpperCase());
}

app/lib/systems.mjs.source:
// The network of systems at /systems and each system at /systems/<id>: Capsid's public model
// (data/system-model.json, the document Capsid serves at /public/model/v1.json) checked, then shown
// by Capsomer's system map, the network as hexagons (the plain map of cards a tab away) and one system at level 2.
//
// Every system is drawn whole, a private repo's included, fully wired like the public ones; a private
// system carries no repo link. The file is refused unless every key is one the published shape allows and a private
// system names no repo, so a mistake upstream stops the build rather than reaching the page.
// The shape, its checks, the explorer's addresses and the Markdown twin are Capsomer's
// (capsomer/behavior/system-model); what is here is this site's paths and words.
import { modelMapData } from "capsomer/behavior/system-map";
// Zod builds its parsers, and probes `new Function`, when a schema is created, so the flag goes first (site-runtime ./zod-jitless).
import "@dustinedwards/site-runtime/zod-jitless";
import { parsePublicModel } from "capsomer/behavior/system-model";

export const SYSTEMS_PATH = "/systems";

/** @typedef {import("capsomer/behavior/system-model").PublicModel} SystemModel */
/** @typedef {SystemModel["systems"][number]} ModelSystem */

/**
 * The checked model, or a thrown error naming every problem: a bad file stops the build.
 * @param {unknown} raw
 * @returns {SystemModel}
 */
export function loadSystemModel(raw) {
  const result = parsePublicModel(raw);
  if (!result.ok)
    throw new Error(`data/system-model.json is refused:\n  ${result.problems.join("\n  ")}`);
  return result.model;
}

/** The page of one system: Capsomer's system map at level 2. @param {string} id */
export const systemPath = (id) => `${SYSTEMS_PATH}/${encodeURIComponent(id)}`;

/**
 * What Capsomer's map shows, the same as the explorer's (Capsomer's modelMapData): every system, linking to its own
 * page here, every line and the parts.
 * @param {SystemModel} model
 */
export const mapData = (model) => modelMapData(model, systemPath);

/**
 * The words of the /systems.md twin, for Capsomer's modelMarkdown and systemMarkdown.
 * @param {SystemModel} model
 * @param {string} origin
 */
export const twinOptions = (model, origin) => ({
  origin,
  pageHref: systemPath,
  title: "Systems",
  intro: `The systems Dustin Edwards runs. Public model of ${model.as_of}.`,
  rings: { core: "Runs everything", shared: "Shared parts", used: "What people use" },
});

/**
 * The repo link a public system shows: its first repo, unless it has none.
 * @param {ModelSystem} s
 */
export const repoOf = (s) => (s.private ? undefined : s.repos?.[0]);

app/kb/admin.mjs.source:
// The admin's Knowledge Base page (docs/KNOWLEDGE-BASE.md, step 2), the part that needs no runtime: its tabs and their
// counts, the search over a base's entries, and the Needs info list, every recorded gap of every entry and registry item
// on one screen. Pure, so node:test holds it; the route passes in the rows it read from D1. Read-only: nothing here writes.

import { foldText } from "../lib/cv/view.mjs";
import { BASES } from "./bases.mjs";
import { labelGaps } from "./gap-labels.mjs";
import { hasItemPage, itemPath, kindPath } from "./registry/catalog.mjs";
import { isGap } from "./procedures/gap.mjs";
import { KINDS } from "./registry/kinds.mjs";

export const KB_ADMIN_PATH = "/admin/kb";

/** Where an entry's file is edited (step 3). @param {string} slug */
export const entryEditHref = (slug) => `${KB_ADMIN_PATH}/entry/${slug}`;

/** Where a registry item's file is edited (step 3). @param {string} kind @param {string} id */
const itemEditHref = (kind, id) => `${KB_ADMIN_PATH}/item/${kind}/${id}`;

/** The tab that lists every gap, beside one tab per base. */
export const NEEDS_INFO = "needs-info";

/**
 * @typedef {{
 *   slug: string,
 *   path: string,
 *   profile: string,
 *   title: string,
 *   description: string,
 *   draft: boolean,
 *   version: string | null,
 *   updated: string | null,
 *   gaps: Array<{ field: string, reason: string, where?: string[], section?: string }>,
 * }} KbEntry
 *
 * @typedef {{ kind: string, id: string, name: string, status: string, fields: Record<string, unknown> }} KbItem
 *
 * @typedef {{ what: string, kindLabel: string, href: string, editHref: string, field: string, label: string, reason: string }} KbGap
 */

/** The tab a `?tab=` value names, else the first base. @param {string | null} value */
export function resolveTab(value) {
  if (value === NEEDS_INFO || BASES.some((base) => base.id === value))
    return /** @type {string} */ (value);
  return /** @type {string} */ (BASES[0]?.id);
}

/** A tab's address, keeping the search only where it still applies (a base's list). @param {string} tab @param {string} [q] */
export function tabHref(tab, q = "") {
  const params = new URLSearchParams({ tab });
  if (q && tab !== NEEDS_INFO) params.set("q", q);
  return `${KB_ADMIN_PATH}?${params}`;
}

/**
 * Every tab with its count, read from the same rows the lists are drawn from: one per base, then Needs info.
 *
 * @param {KbEntry[]} entries
 * @param {KbGap[]} gaps
 */
export function kbTabs(entries, gaps) {
  return [
    ...BASES.map((base) => ({
      id: base.id,
      label: base.name,
      count: entries.filter((e) => e.profile === base.profile).length,
    })),
    { id: NEEDS_INFO, label: "Needs info", count: gaps.length },
  ];
}

/**
 * A base's entries, narrowed by a search over the title, description and slug (case and accents folded), in title order.
 *
 * @param {KbEntry[]} entries
 * @param {string} tab
 * @param {string} [q]
 */
export function baseEntries(entries, tab, q = "") {
  const base = BASES.find((b) => b.id === tab);
  if (!base) return [];
  const needle = foldText(q);
  return entries
    .filter((e) => e.profile === base.profile)
    .filter(
      (e) => needle === "" || foldText(`${e.title} ${e.description} ${e.slug}`).includes(needle),
    )
    .sort((a, b) => foldText(a.title).localeCompare(foldText(b.title), "en", { numeric: true }));
}

/** Where an item is read: its own page, or its kind's table where the kind has no item pages. @param {KbItem} item */
function itemHref(item) {
  return hasItemPage(item.kind) ? itemPath(item.kind, item.id) : kindPath(item.kind);
}

/**
 * Every recorded gap (`MISSING: <why>`), entries first in title order, then registry items in the registry's order, each
 * with the field and the reason as written.
 *
 * @param {KbEntry[]} entries
 * @param {KbItem[]} items
 * @returns {KbGap[]}
 */
export function needsInfo(entries, items) {
  const profileName = Object.fromEntries(BASES.map((base) => [base.profile, base.singular]));
  const fromEntries = [...entries]
    .sort((a, b) => foldText(a.title).localeCompare(foldText(b.title), "en", { numeric: true }))
    .flatMap((e) =>
      labelGaps(e.gaps, e.profile).map((gap) => ({
        what: e.title,
        kindLabel: profileName[e.profile] ?? e.profile,
        href: e.path,
        editHref: `${entryEditHref(e.slug)}#${gap.anchor}`,
        field: gap.field,
        label: gap.label,
        reason: gap.reason,
      })),
    );
  const fromItems = items.flatMap((item) =>
    labelGaps(
      Object.entries(item.fields)
        .filter(([, value]) => isGap(value))
        .map(([field, value]) => ({ field, reason: String(value).replace(/^MISSING:\s*/, "") })),
      null,
    ).map((gap) => ({
      what: item.name,
      kindLabel: capitalize(KINDS[item.kind]?.singular ?? item.kind),
      href: itemHref(item),
      editHref: `${itemEditHref(item.kind, item.id)}#${gap.anchor}`,
      field: gap.field,
      label: gap.label,
      reason: gap.reason,
    })),
  );
  return [...fromEntries, ...fromItems];
}

/** @param {string} word */
function capitalize(word) {
  return word.charAt(0).toUpperCase() + word.slice(1);
}

app/kb/form.mjs.source:
// The Knowledge Base's form editor, the part that needs no runtime (docs/KNOWLEDGE-BASE.md): a file read into a form's
// model, and a form's model written back into the file. The file stays the source, so what the form
// writes goes through the same save and the same checks as the raw editor. What the form did not touch is written back
// byte for byte: a front-matter field whose value is unchanged keeps the text it was written in, and a step keeps its
// lines, so a save from the form changes only what was changed. formToFile(fileToForm(raw)) === raw for every file.

import { matter, stringifyMatter } from "@drdustinedwards/site-helpers/matter";

import { yamlPlain } from "../lib/yaml-plain.mjs";

/** YAML through Prelum's matter, the reader every content file is parsed with, so the form reads a field as the compile does. */
const yaml = {
  /** @param {string} text */
  load: (text) => /** @type {Record<string, unknown>} */ (matter(`---\n${text}\n---\n`).data),
  /** @param {Record<string, unknown>} value */
  dump: (value) =>
    stringifyMatter("", value)
      .replace(/^---\n/, "")
      .replace(/\n---\n*$/, "\n"),
};

/**
 * @typedef {{ kind: string, text: string, indent: string } | { raw: string }} StepLine
 * @typedef {{ number: number, text: string, lines: StepLine[], blanksBefore: number }} FormStep
 * @typedef {{ type: "prose", text: string } | { type: "steps", start: number, steps: FormStep[] }} FormBlock
 * @typedef {{ heading: string, blocks: FormBlock[] }} FormSection
 * @typedef {{ intro: string, sections: FormSection[] }} FormBody
 * @typedef {{ data: Record<string, unknown>, order: string[], body: FormBody | null }} FormModel
 */

/** The step flags the procedure format has (docs/PROCEDURES.md), in the order the form offers them. */
export const STEP_FLAGS = /** @type {const} */ ([
  "CRITICAL",
  "PAUSE POINT",
  "WHY",
  "EXPECT",
  "SPIN",
  "TROUBLESHOOTING",
  "CALC",
  "CHALLENGE",
  "SOLUTION",
]);

const FRONT = /^---\r?\n([\s\S]*?)\r?\n---(\r?\n|$)/;
const KEY = /^([A-Za-z_][\w-]*):(?:\s|$)/;
const DAY = /^\d{4}-\d{2}-\d{2}$/;

/** Equal as data, whatever order an object's keys came in. @param {unknown} a @param {unknown} b @returns {boolean} */
function sameValue(a, b) {
  if (Array.isArray(a) || Array.isArray(b)) {
    return (
      Array.isArray(a) &&
      Array.isArray(b) &&
      a.length === b.length &&
      a.every((x, i) => sameValue(x, b[i]))
    );
  }
  if (a && b && typeof a === "object" && typeof b === "object") {
    const ka = Object.keys(a);
    const kb = Object.keys(b);
    return (
      ka.length === kb.length &&
      ka.every((k) => sameValue(/** @type {any} */ (a)[k], /** @type {any} */ (b)[k]))
    );
  }
  return a === b;
}

/**
 * The file's front matter, split into each top-level field's own text. Lines before the first field (a comment) are
 * kept as the prelude.
 *
 * @param {string} raw
 */
export function splitFile(raw) {
  const match = FRONT.exec(raw);
  if (!match) throw new Error("the file does not start with front matter between --- lines");
  const lines = (match[1] ?? "").split(/\r?\n/);
  /** @type {string[]} */
  const prelude = [];
  /** @type {Array<{ key: string, text: string }>} */
  const fields = [];
  for (const line of lines) {
    const key = KEY.exec(line);
    if (key) fields.push({ key: /** @type {string} */ (key[1]), text: line });
    else if (fields.length > 0)
      /** @type {{ text: string }} */ (fields[fields.length - 1]).text += `\n${line}`;
    else prelude.push(line);
  }
  return { prelude, fields, after: match[2] ?? "\n", body: raw.slice(match[0].length) };
}

/** One field's value, read from its own text. @param {string} text */
function readField(text) {
  const parsed = yaml.load(text);
  return parsed && typeof parsed === "object" ? yamlPlain(Object.values(parsed)[0]) : undefined;
}

/** A plain one-line string YAML reads back as itself, unquoted. @param {string} value */
function bare(value) {
  if (value === "" || value !== value.trim() || /[\n:#]|^[-?[\]{},&*!|>'"%@`]/.test(value))
    return false;
  try {
    return yaml.load(`v: ${value}`)["v"] === value;
  } catch {
    return false;
  }
}

/** A field written fresh, for a value the form changed. @param {string} key @param {unknown} value */
function writeField(key, value) {
  if (typeof value === "string") {
    if (DAY.test(value) || bare(value)) return `${key}: ${value}`;
    return `${key}: ${JSON.stringify(value)}`;
  }
  if (typeof value === "number" || typeof value === "boolean") return `${key}: ${value}`;
  return yaml.dump({ [key]: value }).replace(/\n$/, "");
}

/**
 * A step list's own lines: a numbered item, then its indented lines (flags, commands, wrapped words), with the blank
 * lines inside the list kept where they were.
 *
 * @param {string[]} lines
 * @param {number} i the index of the item line
 */
function readStep(lines, i) {
  const item = /^(\d+)\.\s+(.*)$/.exec(lines[i] ?? "");
  /** @type {StepLine[]} */
  const stepLines = [];
  let j = i + 1;
  while (j < lines.length) {
    const next = lines[j] ?? "";
    if (/^\s{2,}\S/.test(next)) {
      const flag =
        /^(\s+)>\s*(CRITICAL|PAUSE POINT|WHY|TROUBLESHOOTING|EXPECT|SPIN|CALC|CHALLENGE|SOLUTION)\s*:\s?(.*)$/.exec(
          next,
        );
      // A flag is the form's to edit when its line is exactly what the form would write back.
      if (flag && next === `${flag[1]}> ${flag[2]}: ${flag[3]}`)
        stepLines.push({
          kind: /** @type {string} */ (flag[2]),
          text: flag[3] ?? "",
          indent: flag[1] ?? "   ",
        });
      else stepLines.push({ raw: next });
      j += 1;
    } else if (next.trim() === "" && /^\s{2,}\S/.test(lines[j + 1] ?? "")) {
      stepLines.push({ raw: next });
      j += 1;
    } else break;
  }
  return {
    step: { number: Number(item?.[1]), text: item?.[2] ?? "", lines: stepLines, blanksBefore: 0 },
    next: j,
  };
}

/** A section's lines as blocks: step lists, and everything else as prose kept line for line. @param {string[]} lines */
function readBlocks(lines) {
  /** @type {FormBlock[]} */
  const blocks = [];
  /** @type {string[]} */
  let prose = [];
  let inFence = false;
  let i = 0;
  const flush = () => {
    if (prose.length > 0) blocks.push({ type: "prose", text: prose.join("\n") });
    prose = [];
  };
  while (i < lines.length) {
    const text = lines[i] ?? "";
    if (text.startsWith("```")) inFence = !inFence;
    if (!inFence && /^\d+\.\s/.test(text)) {
      flush();
      /** @type {FormStep[]} */
      const steps = [];
      let blanks = 0;
      while (i < lines.length && /^\d+\.\s/.test(lines[i] ?? "")) {
        const { step, next } = readStep(lines, i);
        steps.push({ ...step, blanksBefore: blanks });
        i = next;
        // Blank lines between two items keep the list going; any other line ends it.
        blanks = 0;
        let k = i;
        while (k < lines.length && (lines[k] ?? "").trim() === "") k += 1;
        if (k > i && /^\d+\.\s/.test(lines[k] ?? "")) {
          blanks = k - i;
          i = k;
        }
      }
      blocks.push({ type: "steps", start: steps[0]?.number ?? 1, steps });
      continue;
    }
    prose.push(text);
    i += 1;
  }
  flush();
  return blocks;
}

/**
 * A procedure's body as the form shows it: the intro, then each `## ` section with its prose and its steps.
 *
 * @param {string} body
 * @returns {FormBody}
 */
function readBody(body) {
  const lines = body.split("\n");
  /** @type {string[]} */
  const intro = [];
  /** @type {Array<{ heading: string, lines: string[] }>} */
  const raw = [];
  let inFence = false;
  for (const line of lines) {
    if (line.startsWith("```")) inFence = !inFence;
    if (!inFence && line.startsWith("## ")) raw.push({ heading: line.slice(3), lines: [] });
    else if (raw.length > 0)
      /** @type {{ lines: string[] }} */ (raw[raw.length - 1]).lines.push(line);
    else intro.push(line);
  }
  return {
    intro: intro.join("\n"),
    sections: raw.map((s) => ({ heading: s.heading, blocks: readBlocks(s.lines) })),
  };
}

/** A step's lines, numbered. @param {FormStep} step @param {number} number */
function writeStep(step, number) {
  const lines = [`${number}. ${step.text}`];
  for (const line of step.lines) {
    if ("raw" in line) lines.push(line.raw);
    else lines.push(`${line.indent || "   "}> ${line.kind}: ${line.text}`);
  }
  return [...Array(step.blanksBefore).fill(""), ...lines].join("\n");
}

/** The body the form describes. A step list is numbered from where it started, in the order the form put it. @param {FormBody} body */
function writeBody(body) {
  const parts = [body.intro];
  for (const section of body.sections) {
    const lines = [`## ${section.heading}`];
    for (const block of section.blocks) {
      if (block.type === "prose") lines.push(block.text);
      else lines.push(block.steps.map((step, i) => writeStep(step, block.start + i)).join("\n"));
    }
    parts.push(lines.join("\n"));
  }
  return parts.join("\n");
}

/**
 * A file as a form's model: every front-matter field's value, in the file's order, and for a procedure its body.
 *
 * @param {string} raw
 * @param {{ body?: boolean }} [options] body: false for a registry item, whose file is its front matter alone
 * @returns {FormModel}
 */
export function fileToForm(raw, options = {}) {
  const { fields, body } = splitFile(raw);
  /** @type {Record<string, unknown>} */
  const data = {};
  for (const field of fields) data[field.key] = readField(field.text);
  return {
    data,
    order: fields.map((f) => f.key),
    body: options.body === false ? null : readBody(body),
  };
}

/**
 * The file a form's model describes, written over the file it was read from: an unchanged field keeps its text, a
 * changed one is written fresh, a new one goes after the rest, and a field the form removed (undefined) is left out.
 *
 * @param {string} original
 * @param {FormModel} model
 */
export function formToFile(original, model) {
  const { prelude, fields, after, body } = splitFile(original);
  const known = new Map(fields.map((f) => [f.key, f.text]));
  const keys = [
    ...model.order.filter((k) => known.has(k) || k in model.data),
    ...Object.keys(model.data).filter((k) => !model.order.includes(k)),
  ];
  /** @type {string[]} */
  const out = [...prelude];
  for (const key of new Set(keys)) {
    const value = model.data[key];
    if (value === undefined) continue;
    const text = known.get(key);
    out.push(
      text !== undefined && sameValue(readField(text), value) ? text : writeField(key, value),
    );
  }
  return `---\n${out.join("\n")}\n---${after}${model.body ? writeBody(model.body) : body}`;
}

