// One door from a dictionary entry file to everything derived from it: parse, validate, the entry every
// surface reads. check:content, build:content, sync:content and the Carrel adapter's save all call
// compileDictionaryEntry, so a file CI passes is the file the save accepts and the page draws.

import { contentIdFits } from "../carrel/content-id.mjs";
import { gitBlobSha } from "../content/hashes.mjs";
import { CONTENT_PAGE_PATHS } from "../content-pages.mjs";
import {
  SOFTWARE_LABEL,
  dictionaryEntryMarkdown,
  definedTermJsonLd,
} from "../dictionary-entries.mjs";
import { dictionaryPath, parseDictionaryEntry } from "./parse.mjs";
import { SLUG_PATTERN } from "@drdustinedwards/site-helpers/slug";
import { wideDashError } from "../content/front-matter.mjs";

const DICTIONARY_KIND = "dictionary";

/** Every key a file may carry. Anything else is a typo that would be silently ignored. */
const FRONT_MATTER_FIELDS = new Set([
  "path",
  "term",
  "syllables",
  "ipa",
  "respelling",
  "partOfSpeech",
  "plural",
  "etymology",
  "senses",
  "senseLabels",
  "audio",
  "draft",
]);

const AUDIO_PATTERN = /^\/audio\/[a-z]+\.mp3$/;
const LANGUAGE_PATTERN = /^[a-z]{2,3}$/;
/** A pronunciation clip is a few seconds of speech, not a recording. */
const AUDIO_MAX_BYTES = 32 * 1024;

/**
 * @typedef {object} DictionaryHost
 * @property {(path: string) => Promise<{ size: number, head?: number[] } | null>} audio the repository file at
 *   a site-absolute public path (`/audio/capsid.mp3`), or null when it is not there. `head` is its first two
 *   bytes where the host can read them (CI); the Worker's GitHub listing cannot, so the MPEG frame sync is
 *   checked in CI only.
 *
 * @typedef {{ key: string, path: string }} OtherEntry
 */

/** @param {unknown} value @returns {value is string} */
const isFilled = (value) => typeof value === "string" && value.trim() !== "";

/**
 * @param {Record<string, unknown>} data
 * @returns {string[]}
 */
function shapeProblems(data) {
  /** @type {string[]} */
  const errors = [];
  const bad = (/** @type {string} */ field, /** @type {string} */ message) =>
    errors.push(`${field}: ${message}`);

  for (const field of Object.keys(data)) {
    if (!FRONT_MATTER_FIELDS.has(field))
      bad(field, `is not a field of a dictionary entry (${[...FRONT_MATTER_FIELDS].join(", ")})`);
  }
  for (const field of ["term", "syllables", "ipa", "respelling", "partOfSpeech"]) {
    if (!isFilled(data[field])) bad(field, "is required text");
  }
  if (isFilled(data.ipa) && !/^\/.+\/$/.test(String(data.ipa)))
    bad("ipa", "sits between slashes, as /ˈkæp.sɪd/");
  if (isFilled(data.respelling) && !/^[A-Za-z-]+$/.test(String(data.respelling)))
    bad("respelling", "is letters and hyphens only, as KAP-sid");
  if (
    isFilled(data.term) &&
    isFilled(data.syllables) &&
    String(data.syllables).replaceAll("·", "") !== String(data.term).toLowerCase()
  ) {
    bad(
      "syllables",
      `joined without its dots it is "${String(data.syllables).replaceAll("·", "")}", not the term "${String(data.term).toLowerCase()}" in lower case`,
    );
  }
  if (data.plural !== undefined && data.plural !== null) {
    if (!Array.isArray(data.plural) || data.plural.length === 0 || !data.plural.every(isFilled)) {
      bad("plural", "is a list of forms, or absent");
    }
  }
  if (!Array.isArray(data.etymology) || data.etymology.length === 0) {
    bad("etymology", "is a list: text, and [language, word] pairs for foreign words");
  } else {
    data.etymology.forEach((part, i) => {
      const pair =
        Array.isArray(part) &&
        part.length === 2 &&
        LANGUAGE_PATTERN.test(String(part[0])) &&
        isFilled(part[1]);
      if (!(typeof part === "string" && part !== "") && !pair) {
        bad(
          `etymology[${i}]`,
          "is text, or a [language, word] pair with a language code such as la",
        );
      }
    });
  }
  if (!Array.isArray(data.senses) || data.senses.length !== 2 || !data.senses.every(isFilled)) {
    bad("senses", "is exactly two senses: the word's meaning, then the software");
  }
  const labels = data.senseLabels;
  if (
    !Array.isArray(labels) ||
    labels.length !== 2 ||
    labels[0] !== null ||
    labels[1] !== SOFTWARE_LABEL
  ) {
    bad(
      "senseLabels",
      `is [null, ${SOFTWARE_LABEL}]: sense 1 carries no label, and sense 2 is the software`,
    );
  }
  if (data.draft !== undefined && typeof data.draft !== "boolean")
    bad("draft", `is ${JSON.stringify(data.draft)}; it is true or false`);
  // The entries describe the words and the software, and say nothing possessive about the site's owner.
  if (/Dustin/.test(JSON.stringify(data)))
    bad("front matter", "names the site's owner; an entry says nothing possessive about him");
  return errors;
}

/**
 * The entry as the surfaces read it, in the order the page, the twin and the search record expect.
 *
 * @param {Record<string, unknown>} data a file's front matter that passed shapeProblems
 * @returns {import("../dictionary-entries.mjs").DictionaryEntry}
 */
function entryFromData(data) {
  return {
    path: String(data.path),
    term: String(data.term),
    syllables: String(data.syllables),
    ipa: String(data.ipa),
    respelling: String(data.respelling),
    partOfSpeech: String(data.partOfSpeech),
    plural: Array.isArray(data.plural) ? data.plural.map(String) : null,
    etymology: /** @type {import("../dictionary-entries.mjs").EtymologyPart[]} */ (
      /** @type {unknown[]} */ (data.etymology).map((part) =>
        Array.isArray(part) ? [String(part[0]), String(part[1])] : String(part),
      )
    ),
    senses: /** @type {[string, string]} */ (/** @type {unknown[]} */ (data.senses).map(String)),
    senseLabels: [null, SOFTWARE_LABEL],
    audio: String(data.audio),
  };
}

/**
 * @param {object} input
 * @param {string} input.key the file's name without `.md`
 * @param {string} input.raw the whole file
 * @param {{ findWideDashes: (text: string) => Array<{ line: number, column: number, char: string, excerpt: string }> }} input.pipeline
 * @param {DictionaryHost} input.host
 * @param {OtherEntry[]} [input.others] every OTHER entry, for uniqueness
 * @returns {Promise<
 *   | { ok: false, errors: string[] }
 *   | { ok: true, errors: [], key: string, entry: import("../dictionary-entries.mjs").DictionaryEntry, draft: boolean,
 *       body: string, sourcePath: string, sourceBlobSha: string }
 * >}
 */
export async function compileDictionaryEntry({ key, raw, pipeline, host, others = [] }) {
  const file = dictionaryPath(key);
  const parsed = parseDictionaryEntry({ file, raw });
  const errors = [...parsed.problems, ...pipeline.findWideDashes(raw).map(wideDashError)];
  if (parsed.problems.length > 0) return { ok: false, errors };

  if (!SLUG_PATTERN.test(key))
    errors.push(`the file name "${key}" is not a lowercase kebab-case key`);
  else if (!contentIdFits(DICTIONARY_KIND, key))
    errors.push(`the key "${key}" is too long for a Carrel id`);
  errors.push(...shapeProblems(parsed.data));

  const path = typeof parsed.data.path === "string" ? parsed.data.path : "";
  if (
    !path.startsWith("/software/") ||
    !(/** @type {readonly string[]} */ (CONTENT_PAGE_PATHS).includes(path))
  ) {
    errors.push(
      `path: "${path}" is not a registered Software page (CONTENT_PAGE_PATHS in app/lib/content-pages.mjs); an entry opens a named software page`,
    );
  } else if (path !== `/software/${key}`) {
    errors.push(
      `path: ${path} belongs in ${dictionaryPath(path.slice("/software/".length))}; the file name is the entry's key`,
    );
  }
  const taken = others.find((other) => other.path === path);
  if (path && taken)
    errors.push(`path: ${path} already has an entry (${taken.key}); a page opens with one entry`);

  const audio = typeof parsed.data.audio === "string" ? parsed.data.audio : "";
  if (!AUDIO_PATTERN.test(audio)) {
    errors.push(
      `audio: "${audio}" is not a clip under /audio/ named in lower-case letters, as /audio/name.mp3`,
    );
  } else {
    const clip = await host.audio(audio);
    if (!clip)
      errors.push(
        `audio: ${audio} is not in the repository (public${audio}); a referenced clip must exist, and uploading one is a code change`,
      );
    else {
      if (clip.size >= AUDIO_MAX_BYTES)
        errors.push(
          `audio: ${audio} is ${clip.size} bytes; a pronunciation clip is under ${AUDIO_MAX_BYTES}`,
        );
      // An MPEG audio frame sync, not an HTML error page saved under an .mp3 name.
      if (clip.head && (clip.head[0] !== 0xff || ((clip.head[1] ?? 0) & 0xe0) !== 0xe0)) {
        errors.push(`audio: ${audio} does not start with an MPEG audio frame`);
      }
    }
  }
  if (errors.length > 0) return { ok: false, errors };

  const entry = entryFromData(parsed.data);
  // What the twin and the JSON-LD say, each a function of the entry alone: a file that passes cannot fail the page.
  const twin = dictionaryEntryMarkdown(entry).split("\n");
  if (!twin.includes(`2. *${SOFTWARE_LABEL}.* ${entry.senses[1]}`))
    errors.push("twin: sense 2 does not carry the software label in its own line");
  if (definedTermJsonLd(entry, "https://example.invalid").description !== entry.senses[1])
    errors.push("JSON-LD: the DefinedTerm does not describe the software (sense 2)");
  if (errors.length > 0) return { ok: false, errors };

  return {
    ok: true,
    errors: [],
    key,
    entry,
    draft: parsed.data.draft === true,
    body: parsed.body,
    sourcePath: file,
    sourceBlobSha: await gitBlobSha(raw),
  };
}

app/lib/phages/compile.mjs.source:
// The one door from a phage file to the row the phage table on /research/phages is drawn from (docs/PHAGES.md):
// parse, validate, hash, and the markdown a row becomes. build:content, sync:content, the gates and the adapter's
// phage save all call compilePhage, and the page compile (app/lib/pages/compile.mjs) calls expandPhagePage with
// the rows, so a file CI passes is the file the save accepts and the page draws. Pure and dependency-light, so
// the Worker and the Node scripts import the same module.
//
// A phage is ONE record: the row's fields (name, year, host, county, notes) and the PhagesDB link fields. The validator REFUSES any other field, so nothing a
// visitor cannot already read in the table can enter the repository or D1: no sample, location beyond the county
// the table shows, or personal data.

import { gitBlobSha } from "../content/hashes.mjs";
import { foldText } from "../cv/view.mjs";
import { phagesDbUrl } from "../phage-table.mjs";
import { parseFrontMatter, wideDashError } from "../content/front-matter.mjs";

export const PHAGES_DIR = "content/phages";

/** The repository path of a phage's file, from its file key (the name in lower case). */
export function phagePath(/** @type {string} */ slug) {
  return `${PHAGES_DIR}/${slug}.md`;
}

/** The one page the table is drawn into. */
export const PHAGES_PAGE_PATH = "/research/phages";

/**
 * Where the page file says the table goes. It stands alone on its line in the page's file, and the page compile
 * replaces it BEFORE rendering, so the HTML, the twin, the table of contents, the dataset facts and the search
 * record all come from one text. The page's prose, its headings and the table's caption stay in the page file.
 */
export const TABLE_MARKER = "<!-- phages:table -->";

/**
 * The pages, besides the table's, whose text carries {{phage...}} tokens. A phage write re-derives each of them
 * (app/lib/phages/save.server.ts), so this list and the pages must agree: test/phages.test.mjs fails when a page
 * file uses a token and is not here, or is here and uses none.
 */
export const PHAGE_FACT_PAGES = /** @type {const} */ ([
  "/research",
  "/research/bacteriophages",
  "/research/science-education",
]);

/** The two hosts the table names, as the table's cell and the facet write them. A new host is code. */
export const HOSTS = Object.freeze({
  smegmatis: { short: "*M. smegmatis* mc²155", long: "*Mycobacterium smegmatis* mc²155" },
  foliorum: { short: "*M. foliorum*", long: "*Microbacterium foliorum*" },
});

/** The table's columns, in order: the header the page has always had. */
const TABLE_HEADER =
  "| Phage | Year | Host | County | PhagesDB | Paper |\n|---|---|---|---|---|---|";

const STATE = "Texas";
const FIELDS = [
  "name",
  "year",
  "host",
  "county",
  "phagesdb",
  "paper",
  "formerly",
  "note",
  "genome_bp",
  "genes",
];
const REQUIRED = ["name", "year", "host", "county", "phagesdb"];

/** A phage's name: letters and digits, so its lower-case form is the file key, the heading id and the old address. */
const NAME_PATTERN = /^[A-Za-z][A-Za-z0-9]*$/;
const SLUG_PATTERN = /^[a-z][a-z0-9]*$/;
/** A PhagesDB record name, as the PhagesDB address spells it. */
const PHAGESDB_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]*$/;
const PAPER_PATTERN = /^[0-9a-z][0-9a-z-]*$/;
const COUNTY_PATTERN = /^(?:Texas|[A-Z][A-Za-z]+(?: [A-Z][A-Za-z]+)* County)$/;
/** A note is a plain sentence: no character that markdown would read as a link, a table cell or emphasis. */
const NOTE_PATTERN = /^[A-Z][A-Za-z0-9 ,.'()%:;-]*\.$/;
const NOTE_MAX = 160;

/**
 * @typedef {"smegmatis" | "foliorum"} HostKey
 * @typedef {{
 *   name: string, year: number, host: HostKey | null, county: string | null, phagesdb: string | null,
 *   paper: string | null, formerly: string | null, note: string | null,
 *   genomeBp?: number | null, genes?: number | null,
 * }} Phage
 * @typedef {{ paper: (slug: string) => Promise<boolean> }} PhageHost
 * `findWideDashes` is injected, as the page compile injects the pipeline's: the Worker loads it lazily.
 * @typedef {{ findWideDashes: (text: string) => Array<{ line: number, column: number, char: string, excerpt: string }> }} PhagePipeline
 */

/** The file key of a phage: its name in lower case, which is also its heading's id on the page. */
export function phageSlug(/** @type {string} */ name) {
  return name.toLowerCase();
}

/** The page's own order: year, then name, folded so case and accents do not matter. @param {Phage} a @param {Phage} b */
export const byYearThenName = (a, b) =>
  a.year - b.year || foldText(a.name).localeCompare(foldText(b.name), "en", { numeric: true });

export function sortPhages(/** @type {Phage[]} */ phages) {
  return [...phages].sort(byYearThenName);
}

/** @param {unknown} value @param {RegExp} pattern @returns {value is string} */
const matches = (value, pattern) => typeof value === "string" && pattern.test(value);

/**
 * Judges one file and, when it passes, builds the phage. Every message the file has is returned, never the
 * first alone, so a writer fixes all of them at once.
 *
 * @param {{ slug: string, raw: string, host: PhageHost, pipeline: PhagePipeline, sourcePath?: string }} input
 * @returns {Promise<
 *   | { ok: false, errors: string[] }
 *   | { ok: true, errors: [], phage: Phage, record: string, sourcePath: string, sourceBlobSha: string }
 * >}
 */
export async function compilePhage({ slug, raw, host, pipeline, sourcePath }) {
  /** @type {string[]} */
  const errors = pipeline.findWideDashes(raw).map(wideDashError);
  const parsed = parseFrontMatter(raw, errors);
  if (!parsed) return { ok: false, errors };
  const data = parsed.data;
  if (parsed.content.trim() !== "")
    errors.push("the body must be empty: a phage is its front matter and nothing else");
  for (const key of Object.keys(data)) {
    if (!FIELDS.includes(key)) {
      errors.push(
        `${key} is not a phage field; a phage carries ${FIELDS.join(", ")} and nothing else (no samples, locations beyond the county, or other personal data)`,
      );
    }
  }
  for (const key of REQUIRED) {
    if (data[key] === undefined)
      errors.push(
        `${key} is required${key === "name" || key === "year" ? "" : " (null where there is none)"}`,
      );
  }

  const {
    name,
    year,
    host: hostKey,
    county,
    phagesdb,
    paper,
    formerly,
    note,
    genome_bp: genomeBp,
    genes,
  } = data;
  if (!matches(name, NAME_PATTERN))
    errors.push(
      `name is ${JSON.stringify(name)}; it is the phage's name: letters and digits, starting with a letter`,
    );
  else if (slug !== phageSlug(name))
    errors.push(
      `name is ${name}, but the file is ${phagePath(slug)}: a phage's file is named for its name in lower case (${phageSlug(name)}.md)`,
    );
  if (!SLUG_PATTERN.test(slug))
    errors.push(
      `"${slug}" is not a phage file key; the file is the name in lower case, such as acorn15.md`,
    );
  if (typeof year !== "number" || !Number.isInteger(year) || year < 2000 || year > 2099) {
    errors.push(`year is ${JSON.stringify(year)}; it is the year the phage was found, four digits`);
  }
  if (hostKey !== undefined && hostKey !== null && !Object.hasOwn(HOSTS, String(hostKey))) {
    errors.push(
      `host is ${JSON.stringify(hostKey)}; it is ${Object.keys(HOSTS).join(" or ")}, or null where no host is on record`,
    );
  }
  if (county !== undefined && county !== null && !matches(county, COUNTY_PATTERN)) {
    errors.push(
      `county is ${JSON.stringify(county)}; it is a Texas county written "Erath County" (or "${STATE}" where only the state is on record), or null`,
    );
  }
  if (phagesdb !== undefined && phagesdb !== null) {
    if (!matches(phagesdb, PHAGESDB_PATTERN)) {
      errors.push(
        `phagesdb is ${JSON.stringify(phagesdb)}; it is the PhagesDB record's name as PhagesDB spells it, or null where this phage has no verified record`,
      );
    } else if (typeof name === "string" && phagesdb.toLowerCase() !== name.toLowerCase()) {
      errors.push(
        `phagesdb is ${phagesdb}, which is not ${name}'s record: a record is this phage's own, and a same-named phage of another lab is not it (set null)`,
      );
    }
  }
  if (paper !== undefined && paper !== null) {
    if (!matches(paper, PAPER_PATTERN))
      errors.push(
        `paper is ${JSON.stringify(paper)}; it is a publication's slug, such as 10-1128-mra-01242-18, or absent`,
      );
    else if (!(await host.paper(paper)))
      errors.push(
        `paper ${paper} is not a publication of this site (/research/publications/${paper}/); the genome announcement is a paper the site holds`,
      );
  }
  if (formerly !== undefined && formerly !== null && !matches(formerly, NAME_PATTERN)) {
    errors.push(
      `formerly is ${JSON.stringify(formerly)}; it is the phage's earlier name, letters and digits, or absent`,
    );
  }
  if (note !== undefined && note !== null) {
    if (!matches(note, NOTE_PATTERN) || note.length > NOTE_MAX) {
      errors.push(
        `note is ${JSON.stringify(note)}; it is one plain sentence of at most ${NOTE_MAX} characters, starting with a capital and ending with a period, with no links or markdown`,
      );
    }
  }
  // The genome announcement's own numbers, so a page states them from the record instead of typing them.
  for (const [field, value, low, high] of /** @type {const} */ ([
    ["genome_bp", genomeBp, 1_000, 10_000_000],
    ["genes", genes, 1, 5_000],
  ])) {
    if (
      value !== undefined &&
      value !== null &&
      (typeof value !== "number" || !Number.isInteger(value) || value < low || value > high)
    ) {
      errors.push(
        `${field} is ${JSON.stringify(value)}; it is a whole number from ${low} to ${high}, or absent`,
      );
    }
  }
  if (errors.length > 0) return { ok: false, errors };

  /** @type {Phage} */
  const phage = {
    name: /** @type {string} */ (name),
    year: /** @type {number} */ (year),
    host: /** @type {HostKey | null} */ (hostKey ?? null),
    county: /** @type {string | null} */ (county ?? null),
    phagesdb: /** @type {string | null} */ (phagesdb ?? null),
    paper: /** @type {string | null} */ (paper ?? null),
    formerly: /** @type {string | null} */ (formerly ?? null),
    note: /** @type {string | null} */ (note ?? null),
    genomeBp: /** @type {number | null} */ (genomeBp ?? null),
    genes: /** @type {number | null} */ (genes ?? null),
  };
  return {
    ok: true,
    errors: [],
    phage,
    record: JSON.stringify(phage),
    sourcePath: sourcePath ?? phagePath(slug),
    sourceBlobSha: await gitBlobSha(raw),
  };
}

/**
 * What only the whole set can say: the files are the table, so an empty set is a fault, two files cannot be one
 * phage, and two phages cannot claim one PhagesDB record.
 *
 * @param {Phage[]} phages
 * @returns {string[]}
 */
export function phageSetErrors(phages) {
  /** @type {string[]} */
  const errors = [];
  if (phages.length === 0)
    errors.push(`${PHAGES_DIR} holds no phage files; the table cannot be empty`);
  const names = new Set();
  const records = new Map();
  for (const { name, phagesdb } of phages) {
    if (names.has(phageSlug(name))) errors.push(`two files are the phage ${name}`);
    names.add(phageSlug(name));
    if (phagesdb !== null) {
      const key = phagesdb.toLowerCase();
      if (records.has(key))
        errors.push(`${name} and ${records.get(key)} claim the same PhagesDB record, ${phagesdb}`);
      records.set(key, name);
    }
  }
  return errors;
}

/** A former name, as the table writes it after the phage's own: " (formerly Jentrie)" or "". */
export function formerlyText(/** @type {Phage} */ { formerly }) {
  return formerly ? ` (formerly ${formerly})` : "";
}

/** One phage's row in the table, in the table's columns. The table is the page's only list of the phages, so a former name and a note ride in it. */
function phageTableRow(/** @type {Phage} */ phage) {
  const cells = [
    `${phage.name}${formerlyText(phage)}`,
    String(phage.year),
    phage.host ? HOSTS[phage.host].short : "",
    phage.county ?? "",
    phage.phagesdb ? `[PhagesDB](${phagesDbUrl(phage.phagesdb)})` : "",
    [phage.paper ? `[Paper](/research/publications/${phage.paper}/)` : "", phage.note ?? ""]
      .filter(Boolean)
      .join(" "),
  ];
  return `| ${cells.join(" | ")} |`;
}

/**
 * The compiled page's HTML with each phage's name cell carrying the phage's file key as its id, so
 * /research/phages#acorn15 names something: markdown cannot write an id, and the anchor checks (check:links, a
 * page save) read the compiled HTML. The served table (app/routes/phages.tsx) carries the same ids.
 *
 * @param {string} path @param {string} html @param {Phage[] | undefined} phages
 */
export function withPhageRowIds(path, html, phages) {
  if (path !== PHAGES_PAGE_PATH || !phages) return html;
  const ids = new Map(phages.map((p) => [`${p.name}${formerlyText(p)}`, phageSlug(p.name)]));
  return html.replace(/<tr>\n<td>([^<]*)<\/td>/g, (row, label) =>
    ids.has(label) ? `<tr>\n<td id="${ids.get(label)}">${label}</td>` : row,
  );
}

/** The table's text: its header and one row per phage, in the page's order, no trailing newline. */
export function phageTableMarkdown(/** @type {Phage[]} */ phages) {
  return [TABLE_HEADER, ...sortPhages(phages).map(phageTableRow)].join("\n");
}

const countFormat = new Intl.NumberFormat("en-US");

/** @param {number[]} years the years a set of phages was found in, as prose: "2017" or "2017 to 2018". */
function yearsText(years) {
  const low = Math.min(...years);
  const high = Math.max(...years);
  return low === high ? String(low) : `${low} to ${high}`;
}

/**
 * What the whole set states, computed from the rows so a page never types it: the count, the span of years, and
 * for each host its count and the years it was used. The page text that used to carry these ("80 phages") drifted
 * from the records; a token reads them instead.
 *
 * @param {Phage[]} phages
 */
function phageFacts(phages) {
  const years = phages.map((p) => p.year);
  /** @type {Record<string, { count: number, firstYear: number, lastYear: number, years: string }>} */
  const host = {};
  for (const key of Object.keys(HOSTS)) {
    const mine = phages.filter((p) => p.host === key);
    if (mine.length > 0) {
      const own = mine.map((p) => p.year);
      host[key] = {
        count: mine.length,
        firstYear: Math.min(...own),
        lastYear: Math.max(...own),
        years: yearsText(own),
      };
    }
  }
  return {
    count: phages.length,
    firstYear: Math.min(...years),
    lastYear: Math.max(...years),
    noHost: phages.filter((p) => p.host === null).length,
    host,
  };
}

const TOKEN = /\{\{\s*([^{}]*?)\s*\}\}/g;
const COMMON_COUNTY = /^phages\.commonCounty\(([a-z0-9,\s]+)\)$/;

/**
 * Replaces the tokens in a page's text with values read from the phage rows. A token that names nothing is an
 * error, never an empty string, so a renamed phage or a missing field cannot blank a sentence quietly.
 *
 *   {{phages.count}}  {{phages.firstYear}}  {{phages.lastYear}}
 *   {{phages.host.smegmatis.count}}  .firstYear  .lastYear  .years   (a host key from HOSTS)
 *   {{phage.loca.bp}}  .genes  .county  .year                          (a phage's file key)
 *   {{phages.commonCounty(godfather,fizzles)}}                         (the county they share; an error if they differ)
 *
 * @param {string} text
 * @param {Phage[] | undefined} phages
 * @returns {{ ok: true, text: string } | { ok: false, errors: string[] }}
 */
export function expandPhageTokens(text, phages) {
  if (!text.includes("{{")) return { ok: true, text };
  if (!phages || phages.length === 0) {
    return {
      ok: false,
      errors: [
        "the page uses {{phage...}} tokens and the phage rows are not loaded: run the content sync (npm run sync:content -- --remote), or sync_phages",
      ],
    };
  }
  const facts = phageFacts(phages);
  const bySlug = new Map(phages.map((p) => [phageSlug(p.name), p]));
  /** @type {string[]} */
  const errors = [];
  /** Only a genome's size takes thousands separators; a year or a count is written plain. @param {string} token @returns {string | number | null} */
  const read = (token) => {
    const common = COMMON_COUNTY.exec(token);
    if (common) {
      const counties = new Set(
        (common[1] ?? "").split(",").map((k) => bySlug.get(k.trim())?.county ?? null),
      );
      const only = [...counties];
      return only.length === 1 && only[0] !== null && only[0] !== undefined ? only[0] : null;
    }
    const parts = token.split(".");
    if (parts[0] === "phages" && parts.length === 2) {
      const value = /** @type {Record<string, unknown>} */ (facts)[parts[1] ?? ""];
      return typeof value === "number" ? value : null;
    }
    if (parts[0] === "phages" && parts[1] === "host" && parts.length === 4) {
      const entry = facts.host[parts[2] ?? ""];
      const value = entry
        ? /** @type {Record<string, unknown>} */ (entry)[parts[3] ?? ""]
        : undefined;
      return typeof value === "number" || typeof value === "string" ? value : null;
    }
    if (parts[0] === "phage" && parts.length === 3) {
      const phage = bySlug.get(parts[1] ?? "");
      if (!phage) return null;
      const value = /** @type {Record<string, number | string | null>} */ ({
        bp: phage.genomeBp ?? null,
        genes: phage.genes ?? null,
        county: phage.county,
        year: phage.year,
      })[parts[2] ?? ""];
      if (value === null || value === undefined) return null;
      return parts[2] === "bp" && typeof value === "number" ? countFormat.format(value) : value;
    }
    return null;
  };
  const out = text.replace(TOKEN, (whole, inner) => {
    const value = read(String(inner).trim());
    if (value === null) {
      errors.push(
        `${whole} names no phage fact (check the token, the phage's file key, and that its record carries the field)`,
      );
      return whole;
    }
    return String(value);
  });
  return errors.length > 0 ? { ok: false, errors } : { ok: true, text: out };
}

const MARKER_LINE = new RegExp(`^${TABLE_MARKER.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}$`, "gm");

/**
 * The text a page body is judged and rendered as. The phage page must carry the marker once, alone on its line,
 * and every other page must carry none: a marker left in prose would render as nothing and hide a missing table.
 *
 * @param {string} path the page's registered path
 * @param {string} body the page's markdown, front matter removed
 * @param {Phage[] | undefined} phages the rows to draw; required for the phage page
 * @returns {{ ok: false, errors: string[] } | { ok: true, markdown: string }}
 */
export function expandPhagePage(path, body, phages) {
  const anywhere = body.split(TABLE_MARKER).length - 1;
  if (path !== PHAGES_PAGE_PATH) {
    return anywhere > 0
      ? { ok: false, errors: [`${TABLE_MARKER} belongs on ${PHAGES_PAGE_PATH} only`] }
      : { ok: true, markdown: body };
  }
  if (!phages || phages.length === 0) {
    return {
      ok: false,
      errors: [
        "the phage table has no rows to draw: the phages table is empty. Run the content sync (npm run sync:content -- --remote), or sync_phages.",
      ],
    };
  }
  if ((body.match(MARKER_LINE) ?? []).length !== 1 || anywhere !== 1) {
    return {
      ok: false,
      errors: [
        `the page must carry ${TABLE_MARKER} exactly once, alone on its line (it has ${anywhere}); the phage rows are drawn there`,
      ],
    };
  }
  return { ok: true, markdown: body.replace(MARKER_LINE, () => phageTableMarkdown(phages)) };
}

app/lib/publications/listing.mjs.source:
/**
 * The publication index (docs/PUBLICATIONS.md): its fields declared once for Capsomer's catalog, so the search box, the
 * topic and other facets, the sort menu, the year headings and the counts all come from this one declaration. Pure
 * over the query string and the papers it is handed. The route adds the citation counts (a D1 read) and the page copy.
 *
 * What did not change, because search engines and the machine-readable gates hold it: `?topic=` is the address of a
 * topic's papers, and exactly the four bare single-topic addresses canonicalise to themselves (`soleTopic`); every other
 * address is a view of the base page.
 */

import { defineCatalog, parseCatalogParams, queryCatalog } from "capsomer/behavior/catalog";

import { unescapeHtml } from "@dustinedwards/site-runtime/html";
import { isShowcase } from "./showcase.mjs";
import { TOPICS, TOPIC_IDS } from "./topics.mjs";

/** @typedef {import("./types.ts").Publication} Publication */
/** @typedef {import("./types.ts").PublicationType} PublicationType */
/** @typedef {import("./types.ts").TopicId} TopicId */

const PUBLICATIONS_BASE = "/research/publications";

const TYPE_LABELS = /** @type {Record<string, string>} */ ({
  article: "Article",
  review: "Review",
  chapter: "Chapter",
  "teaching-resource": "Teaching resource",
});

/** The journal, volume and pages as the page prints them, entities decoded (the year has its own column). @param {Publication} p */
export function venue(p) {
  return unescapeHtml([p.journal, p.volume, p.pages].filter(Boolean).join(", "));
}

/** The papers' catalog. Newest first by default, under a heading for each year; any search or other sort is flat. */
export const PUBLICATIONS = defineCatalog(
  /** @type {import("capsomer/behavior/catalog").CatalogDefinition<Publication>} */ ({
    id: "papers",
    noun: ["paper", "papers"],
    basePath: PUBLICATIONS_BASE,
    itemKey: (p) => p.id,
    defaultSort: "-year",
    group: { field: "year" },
    fields: [
      {
        key: "title",
        label: "Title",
        value: (p) => unescapeHtml(p.title),
        search: 3,
        sort: true,
        column: { header: "Paper" },
      },
      {
        key: "authors",
        label: "Authors",
        value: (p) => p.authors.map((name) => unescapeHtml(name)),
        search: 1,
      },
      {
        key: "journal",
        label: "Journal",
        value: (p) => venue(p),
        search: 2,
        column: { header: "Journal", drop: 1 },
      },
      {
        key: "year",
        label: "Year",
        value: (p) => p.year,
        type: "number",
        sort: { labels: { asc: "oldest first", desc: "newest first" } },
        column: { header: "Year", align: "end", hideWhenGrouped: true },
      },
      {
        key: "topic",
        label: "Topic",
        value: (p) => p.topics,
        facet: {
          kind: "many",
          general: true,
          order: TOPICS.map((t) => t.id),
          label: (v) => TOPICS.find((t) => t.id === v)?.label ?? v,
        },
      },
      {
        key: "type",
        label: "Type",
        value: (p) => p.type,
        facet: { kind: "many", label: (v) => TYPE_LABELS[v] ?? v },
      },
      // Chosen with `?selected=1`, as the page's "Selected" filter always was.
      {
        key: "selected",
        label: "Selected",
        value: (p) => (p.selected ? "1" : null),
        facet: { kind: "one", label: () => "Selected papers" },
      },
      {
        key: "access",
        label: "Access",
        value: (p) => (p.isOpenAccess ? "open" : null),
        facet: { kind: "one", label: () => "Open access" },
      },
    ],
  }),
);

/**
 * The address a request written in the old parameters should have, or null. The page used `?sort=year-desc|year-asc|title`
 * and `?selected=1|true`; the catalog says `sort=-year|year|title` and `selected=1`. A link in the wild keeps working: it
 * is sent, once, to the same view at its new address. A request with none of the old spellings is left alone.
 *
 * @param {URL} url
 */
export function legacyAddress(url) {
  const params = url.searchParams;
  const sort = params.get("sort");
  const oldSort = sort === "year-desc" || sort === "year-asc";
  const oldSelected = (params.get("selected") ?? "").toLowerCase() === "true";
  if (!oldSort && !oldSelected) return null;
  const next = new URLSearchParams(params);
  if (sort === "year-desc") next.delete("sort");
  if (sort === "year-asc") next.set("sort", "year");
  if (oldSelected) next.set("selected", "1");
  return queryCatalog(PUBLICATIONS, [], parseCatalogParams(PUBLICATIONS, next)).href();
}

/**
 * Only the four bare single-topic URLs self-canonical: the rest are subsets or orderings, and q is unbounded.
 *
 * @param {URLSearchParams} params
 * @returns {TopicId | null}
 */
export function soleTopic(params) {
  const topics = params.getAll("topic").filter((t) => TOPIC_IDS.has(t));
  const KNOWN_PARAMS = new Set(["topic", "q", "sort", "selected"]);
  const hasUnknownParam = [...params.keys()].some((k) => !KNOWN_PARAMS.has(k));
  return topics.length === 1 &&
    params.getAll("topic").length === 1 &&
    !params.has("q") &&
    !params.has("sort") &&
    !params.has("selected") &&
    !hasUnknownParam
    ? /** @type {TopicId} */ (topics[0])
    : null;
}

/**
 * The page's state for an address: the showcase papers run through the catalog, with the span the header states and the
 * canonical topic. Everything shown is in `result`.
 *
 * @param {URLSearchParams} params
 * @param {Publication[]} publications every published paper, newest first (app/db/publications.ts)
 */
export function publicationListing(params, publications) {
  const showcase = publications.filter(isShowcase);
  const result = queryCatalog(PUBLICATIONS, showcase, parseCatalogParams(PUBLICATIONS, params));
  const items = result.rows;
  const span = {
    papers: items.length,
    firstYear: items.length > 0 ? Math.min(...items.map((p) => p.year)) : null,
    lastYear: items.length > 0 ? Math.max(...items.map((p) => p.year)) : null,
    venues: new Set(items.map((p) => p.journal).filter(Boolean)).size,
  };
  return { items, result, span, soleTopic: soleTopic(params), total: showcase.length };
}

